/// \file
/// This file implements the targeting of the Machinelegalizer class for MC6809.
/// \todo This should be generated by TableGen.
//===----------------------------------------------------------------------===//

#include "MC6809LegalizerInfo.h"
#include "MC6809MachineFunctionInfo.h"
#include "MC6809Subtarget.h"
#include "MC6809TargetMachine.h"
#include "MCTargetDesc/MC6809MCTargetDesc.h"

#include "llvm/ADT/STLExtras.h"
#include "llvm/CodeGen/GlobalISel/GenericMachineInstrs.h"
#include "llvm/CodeGen/GlobalISel/LegalizerHelper.h"
#include "llvm/CodeGen/GlobalISel/LegalizerInfo.h"
#include "llvm/CodeGen/GlobalISel/LostDebugLocObserver.h"
#include "llvm/CodeGen/GlobalISel/MIPatternMatch.h"
#include "llvm/CodeGen/GlobalISel/MachineIRBuilder.h"
#include "llvm/CodeGen/MachineFrameInfo.h"
#include "llvm/Support/ErrorHandling.h"
#include <functional>

#define DEBUG_TYPE "mc6809-legalizer"

using namespace llvm;
using namespace TargetOpcode;
using namespace LegalizeActions;
using namespace MIPatternMatch;

MC6809LegalizerInfo::MC6809LegalizerInfo(const MC6809Subtarget &STI) : Subtarget(STI) {
  bool IsHD6309 = Subtarget.has6309();

  LLT p = LLT::pointer(0, 16);
  LLT p1 = LLT::pointer(1, 8); // direct page, bug #178
  LLT s1 = LLT::scalar(1);
  // LLT s3 = LLT::scalar(3);
  LLT s8 = LLT::scalar(8);
  LLT s16 = LLT::scalar(16);
  LLT s32 = LLT::scalar(32);
  LLT s64 = LLT::scalar(64);
  LLT sMax = IsHD6309 ? s32 : s16;
  LLT sMaxLogic = IsHD6309 ? s16 : s8;
  // LLT sOther = IsHD6309 ? s16 : s32;

  auto LegalTypes32 = {p, s8, s16, s32};
  auto LegalTypes16 = {p, s8, s16};
  // LegalAccumulators: kept at {s8, s16} for HD6309 G_MUL (MULD needs s16).
  // G_ADD/G_SUB use s8-only rules — see the byte-decomposition comment below.
  // [[maybe_unused]] preserves the constant for upcoming work without
  // tripping -Wunused-variable on the current rule set.
  [[maybe_unused]] auto LegalAccumulators = {s8, s16};
  auto LegalTypes = IsHD6309 ? LegalTypes32 : LegalTypes16;
  auto LegalTypesWithOne32 = {p, s1, s8, s16, s32};
  auto LegalTypesWithOne16 = {p, s1, s8, s16};
  auto LegalTypesWithOne = IsHD6309 ? LegalTypesWithOne32 : LegalTypesWithOne16;
  auto LegalScalars32 = {s8, s16, s32};
  auto LegalScalars16 = {s8, s16};
  auto LegalScalars = IsHD6309 ? LegalScalars32 : LegalScalars16;
  auto LegalLibcallScalars32 = {s16, s32, s64};
  auto LegalLibcallScalars16 = {s16, s32, s64};
  auto LegalLibcallScalars = IsHD6309 ? LegalLibcallScalars32 : LegalLibcallScalars16;
  auto NotMaxWithOne32 = {s1, s8, s16}, NotMaxWithOne16 = {s1, s8};
  auto NotMaxWithOne = IsHD6309 ? NotMaxWithOne32 : NotMaxWithOne16;



  const auto IsScalarPointer = [](unsigned ScalarTypeIdx, unsigned PointerTypeIdx, auto Predicate) {
    return [=](const LegalityQuery &Query) { return Query.Types[ScalarTypeIdx].isScalar() && Query.Types[PointerTypeIdx].isPointer() && Predicate(Query.Types[ScalarTypeIdx].getSizeInBits(), Query.Types[PointerTypeIdx].getSizeInBits()); };
  };

  const auto ChangeToSameSizeScalar = [](unsigned TypeIdx, unsigned SizeTypeIdx) { return [=](const LegalityQuery &Query) { return std::make_pair(TypeIdx, LLT::scalar(Query.Types[SizeTypeIdx].getSizeInBits())); }; };

  // Bug #138 mode 1: s32 must be legal on plain 6809 too. The IR optimiser
  // strips most G_IMPLICIT_DEF on s32 at -O1+, but -Og deliberately keeps
  // them around for the debugger. Without this, picolibc TUs `str2sig`,
  // `fgetws`, `__bufio_flush_locked`, `hash_seq`, `__big_split` (and any
  // future s32 dead-value site) abort the backend with
  // "unable to legalize instruction: %X:_(s32) = G_IMPLICIT_DEF".
  // s64 is treated the same way — both sit above the per-target
  // `LegalTypesWithOne` ceiling but are required for picolibc compilation.
  getActionDefinitionsBuilder(G_IMPLICIT_DEF)
      .legalFor(LegalTypesWithOne)
      .legalFor({s32, s64});

  getActionDefinitionsBuilder(G_MERGE_VALUES)
      .legalForCartesianProduct({s16, s32, s64}, {s8, s16, s32});
  //.clampScalar(0, *NotMin.begin(), *std::prev(NotMin.end()))
  //.clampScalar(1, *NotMax.begin(), *std::prev(NotMax.end()))
  //.lower();
  //.unsupported();

  getActionDefinitionsBuilder(G_UNMERGE_VALUES)
      .legalForCartesianProduct({s8, s16, s32}, {s16, s32, s64});
  //.clampScalar(0, *NotMax.begin(), *std::prev(NotMax.end()))
  //.clampScalar(1, *NotMin.begin(), *std::prev(NotMin.end()))
  //.lower();
  //.unsupported();

  getActionDefinitionsBuilder({G_EXTRACT, G_INSERT})
      .customForCartesianProduct(LegalTypes, LegalTypes).unsupported();

  // G_ZEXT/G_ANYEXT: (s16/s32, s1) has no selection pattern — custom
  // decompose to s1→s8 (AND #1) then merge with zero bytes.
  // Bug #161: under HD6309, (s32, s8) and (s32, s16) need lowering
  // (chain through the s16 step) — the selector has patterns for s8→s16
  // and s16→s32 but not the direct s8→s32 jump. lowerFor must come
  // BEFORE legalForCartesianProduct so the pair-specific rule wins
  // over the generic legal cartesian product.
  auto &ZExtBuilder = getActionDefinitionsBuilder({G_ZEXT, G_ANYEXT})
      .customIf([=](const LegalityQuery &Query) {
        return Query.Types[1] == s1 &&
               (Query.Types[0] == s16 || Query.Types[0] == s32 ||
                Query.Types[0] == s64);
      });
  if (IsHD6309)
    ZExtBuilder.lowerFor({{s32, s8}});
  ZExtBuilder
      .legalForCartesianProduct(LegalScalars, NotMaxWithOne)
      .lowerFor({{s64, s32}})
      .clampScalar(0, *LegalScalars.begin(), *std::prev(LegalScalars.end()))
      .clampScalar(1, *NotMaxWithOne.begin(), *std::prev(NotMaxWithOne.end()));

  // G_SEXT: native form is SEX (s8 B → s16 D); SEXW exists only on HD6309.
  // The instruction selector has patterns for three shapes:
  //   (s8, s1)  via SEX8Implicit
  //   (s16, s8) via SEX16Implicit (the native SEX)
  //   (s32, s16) via SEX32Implicit (HD6309 only — SEXW: AW → AQ in one insn)
  //
  // For s1-source extends to wider types (s16, s32), we use the MOS-proven
  // pattern (MOSLegalizerInfo.cpp:596-639): emit a G_SELECT on constants
  // `select s1, -1, 0` at the destination width. This completely avoids
  // the chained-sext and upstream lowerEXT's MERGE_VALUES(src, ASHR_HI)
  // pattern that keeps multiple i16 vregs live simultaneously — the #82b
  // regalloc-pressure root cause. The select lowers via MC6809LowerSelect
  // into a branch + constant-materialization diamond, which uses only ONE
  // i16 register (D) at any point.
  //
  // (s32, s16) on HD6309 is legal (SEXW replaces the 4-instr diamond);
  // on plain 6809 it still uses upstream lowerEXT.
  {
    auto &B = getActionDefinitionsBuilder(G_SEXT)
        .legalFor({{s8, s1}, {s16, s8}});
    if (IsHD6309)
      B.legalFor({{s32, s16}});  // Bug #161 Phase 4: SEXW single instruction
    B.lowerFor({{s32, s16}, {s32, s8}, {s64, s16}, {s64, s8}})
        .customFor({{s16, s1}, {s32, s1}, {s64, s1}, {s64, s32}});
  }

  getActionDefinitionsBuilder({G_SEXTLOAD, G_ZEXTLOAD})
      .custom();

  // G_TRUNC: the selector has patterns for `(s1, s8)` (AND #1), and
  // for `(s8, s16)` (extract low byte). For `(s1, s16)` there is no
  // direct pattern — but we cannot lower it via two chained truncs
  // because LegalizationArtifactCombiner::tryCombineTrunc folds
  // adjacent truncs into a single trunc, re-creating the original
  // and causing infinite recursion in the legalizer.
  //
  // Workaround: pre-mask the i16 source with `& 1` and then chain
  // the truncs. The G_AND in the middle is not a trunc, so the
  // combiner does NOT fold it away.
  // Bug #161: under HD6309, s32 (= AQ) is a legal type, so G_TRUNC s32→s16
  // appears in real picolibc code (e.g. nl_langinfo's `(int16_t)((int32_t)x)`
  // patterns, strcmp's signed-difference compute, signal/sig2str range
  // checks). The existing SDAG pattern in MC6809InstrLogical.td:423
  // `(i16 (trunc ACC32)) → (EXTRACT_SUBREG ..., sub_lo_word)` handles
  // this once it reaches selection — we just have to mark it legal.
  // Legalizer-side: add `(s16, s32)` to the legal set; selector picks
  // the sub-register extract for free.
  auto &TruncBuilder = getActionDefinitionsBuilder(G_TRUNC)
      .legalForCartesianProduct({s8}, LegalScalars)
      .legalFor({{s1, s8}});
  if (IsHD6309)
    TruncBuilder.legalFor({{s16, s32}});
  TruncBuilder.customFor({{s1, s16}});
  if (IsHD6309)
    TruncBuilder.customFor({{s1, s32}});  // Bug #243 Class B
  TruncBuilder
      .clampScalar(1, *LegalScalars.begin(), *std::prev(LegalScalars.end()))
      .clampScalar(0, *NotMaxWithOne.begin(), *std::prev(NotMaxWithOne.end()));

  getActionDefinitionsBuilder({G_FREEZE, G_CONSTANT})
      .legalFor(LegalTypesWithOne)
      .clampScalar(0, s8, s16);  // Bug #243 Class B: same rationale as G_PHI

  // Bug #239 / Bug #317 (2026-05-21): PHI legalisation.
  //
  // Bug #239's original behaviour was to narrow s32 G_PHIs to s16,
  // citing ACC32 register-pool exhaustion (AQ + 4 SPILL_Q = 5 slots).
  // That rationale was retired by Bug #296 (2026-05-14) which bumped
  // SPILL_Q to 32 — ACC32 now has 33 slots, plenty for any realistic
  // loop-carried-i64 shape.
  //
  // The narrowing also caused Bug #317 part 2 (Bug #318): on HD6309
  // an s32 G_PHI got UNMERGEd into two s16 halves, each PHI'd
  // separately, then re-MERGEd via Build32_i16i16.  Build32's
  // operand class is ADc (single-register), so regalloc routinely
  // assigned both halves to $ad and materialize-spills couldn't
  // disentangle them — the Build32 expansion blindly emitted
  // `tfr d,w`, byte-swapping the result.  Allowing s32 G_PHI
  // directly avoids the unmerge/merge dance entirely.
  //
  // On HD6309 we allow s32 (and s64 narrowed-to-s32) PHIs natively.
  // On plain MC6809 the s16-narrowing is kept because there's no
  // ACC32 register class.
  if (IsHD6309)
    getActionDefinitionsBuilder(G_PHI)
        .legalFor({p, s1, s8, s16, s32})
        .clampScalar(0, s8, s32);
  else
    getActionDefinitionsBuilder(G_PHI)
        .legalFor({p, s1, s8, s16})
        .clampScalar(0, s8, s16);

  getActionDefinitionsBuilder(G_FCONSTANT)
      .customFor({s32, s64});

  getActionDefinitionsBuilder(G_PTRTOINT)
      .legalIf(IsScalarPointer(0, 1, std::equal_to<>{}))
      .widenScalarIf(IsScalarPointer(0, 1, std::less<>{}), ChangeToSameSizeScalar(0, 1))
      .narrowScalarIf(IsScalarPointer(0, 1, std::greater<>{}), ChangeToSameSizeScalar(0, 1));

  getActionDefinitionsBuilder(G_INTTOPTR)
      .legalIf(IsScalarPointer(1, 0, std::equal_to<>{}))
      .widenScalarIf(IsScalarPointer(1, 0, std::less<>{}), ChangeToSameSizeScalar(1, 0))
      .narrowScalarIf(IsScalarPointer(1, 0, std::greater<>{}), ChangeToSameSizeScalar(1, 0));

  getActionDefinitionsBuilder(G_PTR_ADD)
      .legalFor({{p, s16}, {p, s8}})
      // A direct-page (p1) pointer add is an in-page index that never crosses
      // the 256-byte page, so lower it to an 8-bit in-page add that keeps the
      // result p1 (see legalizeCustom). The offset is clamped to s16 first.
      .customFor({{p1, s16}})
      .clampScalar(1, s16, s16);

  // G_PTRMASK (p0, s16): decompose to PTRTOINT + AND + INTTOPTR.
  // legalFor uses a single type list — must not accidentally match on
  // just type[0]=p0 while ignoring type[1]. Use customIf for the
  // equal-size case (p0, s16) which decomposes in legalizeCustom.
  getActionDefinitionsBuilder(G_PTRMASK)
      .customIf(IsScalarPointer(1, 0, std::equal_to<>{}))
      .widenScalarIf(IsScalarPointer(1, 0, std::less<>{}), ChangeToSameSizeScalar(1, 0))
      .narrowScalarIf(IsScalarPointer(1, 0, std::greater<>{}), ChangeToSameSizeScalar(1, 0));

  // G_ADD / G_SUB legalisation.
  //
  // Plain MC6809: s8 legal, wider types narrow to s8 carry chains
  // (G_UADDO s8 + G_UADDE s8) via the upstream narrowScalarAddSub.
  // MaterializeSpills handles sub-register byte extraction from spilled
  // i16 values (loads from the correct byte offset within the i16 slot).
  //
  // HD6309 (Bug #297, 2026-05-15): s8 + s32 legal, s16 still narrows.
  // The s32 path uses the native page-2 carry chain (ADDW + ADCD /
  // SUBW + SBCD) emitted by expandAddSub_i32_{Mem,Imm,Reg} (commits
  // 2 + 2.1 of Bug #297).  The i32 value lives in physical AQ or a
  // SPILL_Q*N slot (AQc widening above) and the regbank firewall
  // (commit 3, MC6809RegisterBankInfo.cpp) forces ACCUM bank
  // unconditionally so cross-bank phi-handling cannot recur at i32
  // width — addressing the Bug #85b atoi failure shape one level
  // wider.
  //
  // NOTE: making i16 legal at the selector level was attempted and
  // reverted (Bug #85b strategy session).  The i16 path through the
  // selector (INDEX-bank LEA + ACCUM-bank ADDD) produced wrong results
  // at -O0 for atoi-like functions — a reg-bank / phi-handling issue
  // in the i16 add path that doesn't manifest in the i8 carry-chain.
  // The HD6309 s32 path (Bug #297) sidesteps the issue because i32
  // stays in ACCUM bank by construction (no INDEX-bank 32-bit reg
  // exists), and i16 G_ADD/G_SUB still narrows on both subtargets so
  // the cmp_imm_byte_load_phi.ll atoi sentinel codegen is unchanged.
  if (IsHD6309)
    getActionDefinitionsBuilder({G_ADD, G_SUB})
        .legalFor({s8, s32})
        .narrowScalarIf(LegalityPredicates::typeIs(0, s16),
                        LegalizeMutations::changeTo(0, s8))
        .clampScalar(0, s8, s32);
  else
    getActionDefinitionsBuilder({G_ADD, G_SUB})
        .legalFor({s8})
        .clampScalar(0, s8, s8);

  // Bug #311 Phase 2: HD6309 has native ADDW+ADCD for i32 carry chains;
  // selector + expander wire those up (see selectAddO/AddE/SubO/SubE and
  // expandAddSub_i32_* / expandAddSubCarryUse_i32_*).  Making s32 legal
  // here means i32 carry-overflow intrinsics (uadd.with.overflow.i32
  // etc.) stay i32 through to native HD6309 codegen instead of being
  // narrowed to 4 byte-level adds, and i64 G_ADD narrows to 2 i32
  // sub-chains rather than 8 i8 ones.  s16 keeps the existing narrow-
  // to-s8 rule (the i16 carry-chain hits Bug #85b-shape selector
  // issues at -O0 that pre-date Phase 2).  Plain MC6809 unchanged.
  if (IsHD6309)
    getActionDefinitionsBuilder({G_UADDO, G_UADDE, G_USUBO, G_USUBE, G_SADDO, G_SADDE, G_SSUBO, G_SSUBE})
        .legalForCartesianProduct({s8, s32}, {s1, s16})
        .narrowScalarIf(LegalityPredicates::typeIs(0, s16),
                        LegalizeMutations::changeTo(0, s8))
        .clampScalar(0, s1, s32);
  else
    getActionDefinitionsBuilder({G_UADDO, G_UADDE, G_USUBO, G_USUBE, G_SADDO, G_SADDE, G_SSUBO, G_SSUBE})
        .legalForCartesianProduct({s8}, {s1, s16})
        .clampScalar(0, s1, s8);

  // MUL is 8x8→16 on standard 6809. 16x16 only on HD6309 (MULD).
  // On 6809, i8 mul is native (MUL instruction: A×B→D). Wider multiplies
  // 6809: 8-bit MUL is legal, 16-bit narrowed to four 8-bit MULs.
  // NOTE: narrowScalar has a latent spill-register aliasing bug (#51) that
  // manifests when ACC8/ACC16 register classes are expanded (e.g., with
  // imaginary registers). The __mulhi3 libcall path requires calling
  // convention work before it can replace narrowScalar.
  if (IsHD6309) {
    // Bug #266 fix (2026-05-10): route s16 G_MUL to a libcall on HD6309
    // too, matching the plain MC6809 path. Inline MULD with the wider
    // Multiply_i16 Defs (Bug #251: [NZ, AD, AW]) interacted badly with
    // greedy's spill decisions in functions doing byte-level carry
    // chains (qsort family, mem*, time_*) — see Bug #266 four
    // investigation rounds. The libcall has well-defined CC clobbers
    // (no pseudo Defs lying), removing the entire class of bug.
    //
    // The audit confirmed picolibc's libc.a uses ZERO inline muld
    // instructions (probably because the libc-internal multiplies are
    // i32+ which already libcall, and the i16 ones got coalesced into
    // bigger types). Net code-size / perf impact in libc is negligible.
    // App code that does explicit i16 mul takes a small per-call
    // overhead (~8-15 cycles vs inline MULD's 12) — acceptable for
    // closing a four-session correctness regression.
    //
    // Bug #161 round 16's narrowScalar concern is obsolete since
    // s32/s64 are already libcallFor — no narrowing path active.
    getActionDefinitionsBuilder({G_MUL, G_UMULH, G_SMULH})
        .legalFor({s8})
        .libcallFor({s16, s32, s64})
        .clampScalar(0, s1, sMaxLogic);
  } else {
    getActionDefinitionsBuilder({G_MUL, G_UMULH, G_SMULH})
        .legalFor({s8})
        .libcallFor({s16, s32, s64})
        .clampScalar(0, s8, s64);
  }

  getActionDefinitionsBuilder({G_SDIV, G_UDIV, G_SREM, G_UREM})
      .libcallFor(LegalLibcallScalars)
      .clampScalar(0, s16, s32);

  // Bitwise AND/OR/XOR: s8 and s16 legal on all targets.
  // On 6809, i16 pseudos expand post-RA into ANDA+ANDB byte pairs.
  // HD6309 uses native ANDD/ORD/EORD. i32 uses custom legalization
  // that sequences the Store between the two i16 ANDs (avoids ACC16
  // register pressure from having both results live in D simultaneously).
  //
  // Bug #137 prerequisite (2026-04-22): handle s1 via customFor, mirroring
  // MOS at MOSLegalizerInfo.cpp:155-160. The i16 G_ICMP narrowing (#137
  // phase 1) produces i1 bool-combines from byte-compare results, so
  // s1 G_AND/G_OR/G_XOR must have a clean lowering path. The custom
  // handler widens to s8 via G_ZEXT, performs the bitwise op, and
  // truncates back to s1.
  getActionDefinitionsBuilder({G_AND, G_OR, G_XOR})
      .legalFor({s8, s16})
      .customFor({s1, s32})
      .clampScalar(0, s8, s16);

  // Shifts/rotates: shift-by-1 is a native instruction (ASL/LSR/ASR).
  // Constant shifts (s8 amount) are handled in the instruction selector
  // (selectShift16 for i16, selectShiftExtend for decomposed i8).
  // Variable shifts go through custom → legalizeShiftRotate → libcall.
  // Shift-by-1 (s1 amount): legal on all targets (native ASL/LSR/ASR).
  // Shift by s8 amount: custom → legalizeShiftRotate decomposes constants
  // into shift-by-1 chains (G_SHLE/G_LSHRE) and routes variables to libcalls.
  // selectShift16 in the isel handles i16 constant shifts directly via
  // LSL_i16_Reg loops (ASLB+ROLA / LSRA+RORB byte pairs).
  // i64 shifts route to libcalls (__ashldi3/__ashrdi3/__lshrdi3) via
  // the custom handler (shiftRotateLibcall). The rule fires after
  // clampScalar(1) narrows the amount from s64 to s8 — the legalizer
  // retries the chain and customFor({s64},{s8}) matches BEFORE
  // clampScalar(0) can narrow the value from s64 to s32.
  // Rotates don't have i64 libcalls, so they stay on the old path.
  getActionDefinitionsBuilder({G_SHL, G_LSHR, G_ASHR})
      .customForCartesianProduct({s64}, {s8})
      .legalForCartesianProduct(LegalScalars, {s1})
      .customForCartesianProduct(LegalScalars, {s8})
      .customForCartesianProduct({s32}, {s8})
      .clampScalar(1, s1, s8)
      .clampScalar(0, s8, s32);
  // Rotates: s8/s16 by 1 = legal (native ROL/ROR). s8/s16 by s8 =
  // custom (legalizeShiftRotate). s32 = lower to FSHL/FSHR (which
  // the G_FSHL/G_FSHR custom handler decomposes to shifts + OR).
  // Using .lower for s32 avoids narrowScalar on the rotate amount
  // which the upstream LegalizerHelper doesn't support.
  getActionDefinitionsBuilder({G_ROTR, G_ROTL})
      .legalForCartesianProduct(LegalScalars, {s1})
      .customForCartesianProduct(LegalScalars, {s8})
      .lowerIf([=](const LegalityQuery &Q) {
        return Q.Types[0].getSizeInBits() >= 32;
      })
      .clampScalar(1, s1, s8)
      .clampScalar(0, s8, s32);

  // G_ABS: custom legalization to avoid the default ASHR+ADD+XOR pattern
  // which creates massive byte-level shift chains on the 6809. Instead,
  // decompose to compare + negate + select (branch-based).
  // G_ABS: custom legalization decomposes to compare + negate + select,
  // avoiding the default ASHR+XOR pattern that creates massive shift chains.
  getActionDefinitionsBuilder(G_ABS)
      .customFor({s8, s16, s32, s64});

  // G_FSHL/G_FSHR: decompose to two shifts + OR via legalizeFunnelShift.
  // The custom handler produces G_SHL + G_LSHR + G_OR, all of which
  // bottom out in existing legal/libcall rules. Used by compiler-rt's
  // udivdi3/umoddi3/udivmoddi4 long-division algorithms.
  getActionDefinitionsBuilder({G_FSHL, G_FSHR})
      .custom();

  getActionDefinitionsBuilder({G_UMULFIX, G_SMULFIX, G_SMULFIXSAT, G_UMULFIXSAT, G_UDIVFIX, G_SDIVFIX, G_SDIVFIXSAT, G_UDIVFIXSAT, G_FCANONICALIZE})
      .libcall();

  // G_UMULO uses our custom legalizeMultiplyWithOverflow handler, which
  // implements unsigned-multiply-with-overflow as
  //   result   = LHS * RHS
  //   overflow = LHS > UINT_MAX / max(RHS, 1)
  // All four sub-operations (G_MUL, G_UDIV, G_UMAX, G_ICMP) bottom out
  // in libcalls or legal byte-level ops on the supported widths, so the
  // resulting code is small and avoids the regalloc-pressure problems
  // of inline expansions like upstream G_UMULO → G_MUL + G_UMULH + G_ICMP
  // (G_UMULH has no libcall in upstream RTLIB).
  //
  // The previous rule used .libcall() for G_UMULO, but LegalizerHelper::
  // libcall() has no G_UMULO case — so the action was Libcall but the
  // dispatch returned UnableToLegalize. The custom handler was unreachable
  // dead code. Closes bug #83 for s8/s16/s32.
  //
  // s64 is intentionally NOT in the list. The custom handler would produce
  // s64 G_MUL/G_UDIV/G_UMAX/G_ICMP intermediates that bottom out in s64
  // vregs, which MC6809RegisterBankInfo can't classify (it only knows up to
  // 32 bits). The s64 path needs the broader i64 plumbing — see the
  // long-long roadmap memory.
  getActionDefinitionsBuilder(G_UMULO)
      .customForCartesianProduct({s8, s16, s32, s64}, {s1})
      .clampScalar(0, s8, s64);

  getActionDefinitionsBuilder({G_MEMCPY, G_MEMCPY_INLINE, G_MEMMOVE, G_MEMSET})
      .custom();

  // Bug #241: extended set covering the full <math.h> trig / hyperbolic /
  // inverse-trig / exp / mod family. Picolibc provides every libcall here
  // (sinhf/sinh, atanf/atan, etc.). Without these the legalizer aborts at
  // -Og / -Ofast where less inlining preserves the bare opcode.
  getActionDefinitionsBuilder(
      {G_INTRINSIC_TRUNC, G_INTRINSIC_ROUND, G_INTRINSIC_ROUNDEVEN,
       G_FADD, G_FSUB, G_FMUL, G_FMA, G_FMAD, G_FDIV, G_FREM, G_FMODF,
       G_FPOW,
       G_FEXP, G_FEXP2,
       G_FLOG, G_FLOG2, G_FLOG10,
       G_FMINNUM, G_FMAXNUM,
       G_FCEIL, G_FFLOOR, G_FRINT, G_FNEARBYINT,
       G_FSQRT,
       G_FCOS, G_FSIN, G_FTAN, G_FSINCOS,
       G_FACOS, G_FASIN, G_FATAN, G_FATAN2,
       G_FCOSH, G_FSINH, G_FTANH})
      .libcallFor({s32, s64});

  // G_FABS / G_FNEG go via the MC6839 ROM dispatchers (Bug #254 follow-up):
  // the default `lowerFor` produces a bit-AND with 0x7FFFFFFF / a bit-XOR
  // with the sign bit, both of which on MC6809 narrow to heavy __andsi3 /
  // __xorsi3 libcalls (~30 bytes per call site). The ROM-backed
  // __abssf2/__absdf2 / __negsf2/__negdf2 wrappers are each a single
  // ~5-byte LBSR.
  getActionDefinitionsBuilder(G_FABS)
      .libcallFor({s32, s64});
  getActionDefinitionsBuilder(G_FNEG)
      .libcallFor({s32, s64});
  // G_FCOPYSIGN remains on the standard bit-OR lowering — MC6839 has no
  // FCOPYSIGN op exposed.

  getActionDefinitionsBuilder({G_INTRINSIC_LRINT, G_LROUND})
      .libcallForCartesianProduct({s32}, {s32, s64});

  getActionDefinitionsBuilder(G_LLROUND)
      .libcallForCartesianProduct({s64}, {s32, s64});

  getActionDefinitionsBuilder(G_FPEXT)
      .libcallFor({{s64, s32}});

  getActionDefinitionsBuilder(G_FPTRUNC)
      .libcallFor({{s32, s64}});

  getActionDefinitionsBuilder({G_FPTOSI, G_FPTOUI})
      .libcallForCartesianProduct({s32, s64}, {s32, s64}).clampScalar(0, s32, s64);

  getActionDefinitionsBuilder({G_SITOFP, G_UITOFP})
      .libcallForCartesianProduct({s32, s64}, {s32, s64}).clampScalar(1, s32, s64);

  getActionDefinitionsBuilder(G_FCOPYSIGN)
      .lowerFor({{s32, s32}, {s64, s64}});

  // G_IS_FPCLASS: float classification (isnan, isinf, isfinite, etc.).
  // No MC6839 equivalent; lower to comparisons via LegalizerHelper.
  getActionDefinitionsBuilder(G_IS_FPCLASS)
      .lowerFor({{s1, s32}, {s1, s64}});

  // On 6809, s32 load/store has no instruction — narrow to s16 pairs.
  // Bug #161 round 10 (2026-04) extended the narrowing to HD6309 too
  // because every i32 load/store creates an ACC32 vreg (= AQ slot)
  // and the regalloc has only one such slot — 6+ simultaneously-live
  // i32 vregs starved regalloc. Bug #210 round 5 (2026-05-04) tried
  // reverting the HD6309 narrowing for G_LOAD (single LDQ) but found
  // it broke strtol — the LDQ-clobbers-AA/AB chain at high pressure
  // confused __mulsi3 calling convention. Bug #210 was instead closed
  // by routing G_AND/G_OR/G_XOR i32 to libcalls (legalizeBitwise →
  // __andsi3 / __orsi3 / __xorsi3); the in-line UNMERGE/MERGE chain
  // was the actual aqc-creating path. Narrowing stays on both
  // G_LOAD and G_STORE for both targets.
  //
  // Bug #272 Phase B retry via Bug #297 (2026-05-15): s32 G_LOAD /
  // G_STORE are now legal directly on HD6309.  An i32 load lands
  // straight in an ACC32 vreg (AQ or SPILL_Q*N) and is consumed by
  // native ADDW+ADCD / SUBW+SBCD pairs from commits 1-4.  No more
  // narrowing-to-s16 + G_MERGE_VALUES + REG_SEQUENCE chain — that
  // chain was the structural blocker for the earlier Phase B core
  // attempt (`9e782ca31fec`, partial-reverted in `ef11452cc49d`)
  // because REG_SEQUENCE constrained the acc32 vreg to AQ-only
  // allocation, exhausting register supply at >1 live i32 value.
  // Plain MC6809 still narrows (no LDQ instruction).
  // Bug #310 (2026-05-19): G_LOAD with type-size > MMO-size (a
  // partial-width load) has no isel pattern.  Surfaces in
  // vfprintf_s at -Og-hd6309-mame as
  //   %dst:acc32(s32) = G_LOAD %ptr(p0), :: (load (s16), align 1)
  // followed by G_TRUNC %dst back to s16 — only the low 16 bits
  // are used, but the IR generator produced an s32-typed G_LOAD
  // pointing at an s16 MMO.  The legalizer's existing
  // legalForCartesianProduct didn't check MMO size, so the MI
  // sneaked through and the selector hit "cannot select".
  //
  // Route these to `legalizeLoad` (which already handles
  // G_SEXTLOAD/G_ZEXTLOAD by splitting into G_LOAD of MMO-size +
  // S/ZExt to the dst size).  An `anyext`-shaped lowering is
  // sufficient here because the consumer truncates anyway —
  // emit G_ZEXT for safety (defined high bytes; selector handles
  // G_ZEXT cleanly).
  getActionDefinitionsBuilder({G_LOAD, G_STORE})
      .customIf([=](const LegalityQuery &Query) {
        // Bug #310 (2026-05-19) narrowed gate (2026-05-19 PM):
        // the original gate `MemSize < TypeSize` over-fired on
        // many shapes downstream codegen expected to handle
        // natively — caused catastrophic regressions across
        // HD6309-mame levels at the first full bench (175 OK
        // regressed across 5 levels).
        //
        // Restrict to the exact shape seen in vfprintf_s:
        //   %dst:s32 = G_LOAD %ptr(p0), :: (load (s16))
        // (4-byte type, 2-byte MMO).  This is the va_arg-related
        // pattern that hits "cannot select" at the selector —
        // narrower than the original gate and avoids the
        // downstream codegen interactions that broke other
        // tests.  If other partial-width-load shapes surface,
        // add them explicitly rather than re-broadening.
        if (Query.MMODescrs.empty())
          return false;
        if (!Query.Types[0].isScalar())
          return false;
        uint64_t TypeSize = Query.Types[0].getSizeInBits();
        uint64_t MemSize = Query.MMODescrs[0].MemoryTy.getSizeInBits();
        return TypeSize == 32 && MemSize == 16;
      })
      .legalForCartesianProduct(LegalTypes, {p, p1})
      .lowerIfMemSizeNotByteSizePow2()
      .clampScalar(0, s8, sMax);

  // G_GLOBAL_VALUE may produce a p1 pointer (addrspace(1) global);
  // legalize that too so the address can be materialised before the
  // load/store consumes it.
  getActionDefinitionsBuilder({G_FRAME_INDEX, G_GLOBAL_VALUE, G_BRINDIRECT, G_JUMP_TABLE})
      .legalFor({p, p1});

  getActionDefinitionsBuilder(G_VASTART).customFor({p});
  // G_VAARG: dst type can be anything the va_list might hold. The custom
  // handler (legalizeVAArg) is type-agnostic — it loads ValTy.getSizeInBytes()
  // bytes from the current va_list pointer and bumps by that amount. Wider
  // dst types (s32, s64) are picolibc's `%ld` / `%lld` paths through
  // vfiprintf / vfmprintf. The resulting wide G_LOAD is narrowed to s16
  // pairs by the standard G_LOAD legalizer rule's clampScalar, so no extra
  // work is needed here.
  //
  // Closes bug #85 once paired with the matching G_LOAD narrow-scalar path.
  getActionDefinitionsBuilder(G_VAARG)
      .customForCartesianProduct({p, s8, s16, s32, s64}, {p});

  // G_ICMP: s8/s16 native; pointer via custom; s32/s64 via libcall to
  // __{u,}cmp{s,d}i2. Inline i32/i64 compare decomposes into a multi-
  // instruction CC-setting sequence with a conditional-branch tail that
  // regalloc's spill placer can cleave with STY/LDY, clobbering CC.Z and
  // corrupting the branch at runtime (bug #158). Routing to a libcall
  // replaces that whole sequence with one LBSR, which is a hard barrier
  // against regalloc inserting spills in the compare→branch gap.
  getActionDefinitionsBuilder(G_ICMP)
      .legalForCartesianProduct({s1}, {s8, s16})
      .customForCartesianProduct({s1}, {p, s32, s64})
      .clampScalar(1, s8, s16);

  // G_FCMP: no native FP compare — lower to GNU comparison libcalls
  // (__cmpsf2/__cmpdf2 and predicate variants). LegalizerHelper::libcall()
  // handles the return-int-then-compare-to-zero pattern.
  getActionDefinitionsBuilder(G_FCMP)
      .libcallForCartesianProduct({s1}, {s32, s64});

  getActionDefinitionsBuilder(G_BRCOND)
      .legalFor({s1});

  getActionDefinitionsBuilder(G_BRJT)
      .legalForCartesianProduct({p}, LegalScalars)
      .clampScalar(1, s8, sMax);

  // G_SELECT s32/s64: decompose to pairs of narrower selects to avoid
  // multiple ACC16 values competing for D in the PHI path.
  getActionDefinitionsBuilder(G_SELECT)
      .customIf([=](const LegalityQuery &Query) {
        return Query.Types[0] == s32 || Query.Types[0] == s64;
      })
      .legalForCartesianProduct(LegalTypesWithOne, {s1}).clampScalar(0, s8, sMax);

  getActionDefinitionsBuilder({G_SDIVREM, G_UDIVREM, G_DYN_STACKALLOC, G_SEXT_INREG, G_SMULO, G_SMIN, G_SMAX, G_UMIN, G_UMAX, G_UADDSAT, G_SADDSAT, G_USUBSAT, G_SSUBSAT, G_USHLSAT, G_SSHLSAT, G_FPOWI})
      .lower();

  // CTTZ / CTLZ / CTPOP all go to hand-written runtime libcalls
  // (compiler-rt/lib/builtins/mc6809/{ctz,clz,popcount}{qi,hi}2.S for the
  // 8/16-bit forms; the 32/64/128 forms come from upstream compiler-rt).
  // The upstream "lower inline via SWAR" path produces too many simultaneous
  // i16 temps for our regalloc — see bug #73 and the regalloc-strategy
  // discussion. Libcalls put the cost in hand-tuned assembly that uses
  // exactly the registers it needs and saves them via PSHS/PULS.
  //
  // Same-type rules (result and source share the scalar width) avoid the
  // upstream lowerBitCount path that produces (s8, s16) shapes the
  // libcall machinery can't handle.
  getActionDefinitionsBuilder({G_CTTZ, G_CTTZ_ZERO_UNDEF})
      .libcallFor({{s16, s16}, {s32, s32}, {s64, s64}})
      .widenScalarToNextPow2(0, /*Min=*/16)
      .clampScalar(0, s16, s64);

  getActionDefinitionsBuilder({G_CTLZ, G_CTLZ_ZERO_UNDEF})
      .libcallFor({{s16, s16}, {s32, s32}, {s64, s64}})
      .widenScalarToNextPow2(0, /*Min=*/16)
      .clampScalar(0, s16, s64);

  getActionDefinitionsBuilder(G_CTPOP)
      .libcallFor({{s16, s16}, {s32, s32}, {s64, s64}})
      .widenScalarToNextPow2(0, /*Min=*/16)
      .clampScalar(0, s16, s64);

  getActionDefinitionsBuilder(G_BSWAP).legalFor({s16}).libcallFor({s32, s64})
      .clampScalar(0, s16, s64);

  getActionDefinitionsBuilder(G_BITREVERSE).libcallFor(LegalLibcallScalars)
      .clampScalar(0, s8, s64);

  getLegacyLegalizerInfo().computeTables();
  verify(*STI.getInstrInfo());
}

bool MC6809LegalizerInfo::legalizeCustom(LegalizerHelper &Helper, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  MachineRegisterInfo &MRI = MI.getMF()->getRegInfo();
  Helper.MIRBuilder.setInstrAndDebugLoc(MI);
  switch (MI.getOpcode()) {
  default:
    // No idea what to do.
    return false;
  case G_SEXTLOAD:
  case G_ZEXTLOAD:
    return legalizeLoad(Helper, MRI, cast<GAnyLoad>(MI), LocObserver);
  case G_LOAD:
    // Bug #310 (2026-05-19): a G_LOAD whose dst type is larger
    // than its MMO memory type (partial-width load) reaches the
    // customIf gate above.  Handle by routing to legalizeLoad,
    // which already knows how to split G_LOAD/G_*EXTLOAD into a
    // G_LOAD of MMO-size + an extension to the dst size.
    return legalizeLoad(Helper, MRI, cast<GAnyLoad>(MI), LocObserver);
  case G_AND:
  case G_OR:
  case G_XOR:
    return legalizeBitwise(Helper, MRI, MI, LocObserver);
  case G_ICMP: {
    Register Dst = MI.getOperand(0).getReg();
    auto Pred = (CmpInst::Predicate)MI.getOperand(1).getPredicate();
    Register Lhs = MI.getOperand(2).getReg();
    Register Rhs = MI.getOperand(3).getReg();
    MachineIRBuilder &B = Helper.MIRBuilder;
    LLT S16 = LLT::scalar(16);
    LLT OpTy = MRI.getType(Lhs);

    // Pointer compare: convert ptr operands to s16 and reuse the s16 G_ICMP
    // patterns. The hardware CMPD/CMPX instructions don't distinguish pointers
    // from integers. Bug #359: fold a constant operand (the common case being
    // a null check) to a direct s16 G_CONSTANT rather than G_PTRTOINT(const) —
    // the immediate selection patterns (and the index-domain CMPX #imm path)
    // need to recognise it as an immediate, which they can't do through a
    // ptrtoint.
    if (OpTy.isPointer()) {
      auto toS16 = [&](Register R) -> Register {
        // Look through G_PTRTOINT / G_INTTOPTR / COPY to find an underlying
        // G_CONSTANT (a pointer constant such as null carries a p0 type, which
        // getIConstantVRegValWithLookThrough won't treat as an integer
        // constant). Re-materialise it as a plain s16 constant so the
        // index-domain compare can fold it as a CMPX/CMPY #imm immediate.
        Register Cur = R;
        while (Cur.isVirtual()) {
          MachineInstr *D = MRI.getVRegDef(Cur);
          if (!D)
            break;
          unsigned Op = D->getOpcode();
          if (Op == TargetOpcode::G_CONSTANT)
            return B
                .buildConstant(
                    S16, D->getOperand(1).getCImm()->getZExtValue() & 0xffff)
                .getReg(0);
          if (Op == TargetOpcode::G_PTRTOINT || Op == TargetOpcode::G_INTTOPTR ||
              Op == TargetOpcode::COPY) {
            Register N = D->getOperand(1).getReg();
            if (!N.isVirtual())
              break;
            Cur = N;
            continue;
          }
          break;
        }
        return B.buildPtrToInt(S16, R).getReg(0);
      };
      B.buildICmp(Pred, Dst, toS16(Lhs), toS16(Rhs));
      MI.eraseFromParent();
      return true;
    }

    // Bug #301b (2026-05-16): native HD6309 i32 sign-test
    // fast path.  Replaces __cmpsi2 + trunc + icmp eq 0 for the four
    // sign-test shapes:
    //
    //   icmp slt i32 X, 0    →  SignTest_i32 X
    //   icmp sle i32 X, -1   →  SignTest_i32 X       (slt-0 normalised)
    //   icmp sge i32 X, 0    →  XOR (SignTest_i32 X) 1
    //   icmp sgt i32 X, -1   →  XOR (SignTest_i32 X) 1   (sge-0 normalised)
    //
    // SignTest_i32 is a target-specific pseudo (MC6809InstrPseudos.td)
    // whose post-RA expansion tests the i32's MSByte directly via a
    // sub-register read of $aq.MSByte (= $aa) for AQ-allocated src or
    // a direct byte-load `TST <slot+0>,$su` for SPILL_Q*N src.  Bypasses
    // the EXTRACT_*_word_i32 + ACC32_with_sub_hi_byte synthesised-class
    // collapse that triggered Bug #301a in the reverted Option C
    // attempt (`33cfce2ecc7f`).
    //
    // Restricted to HD6309 (the only subtarget where i32 G_LOAD/STORE
    // is native — see the Bug #297 re-land) and i32 width.  i64 is
    // deferred to a future Bug #301c follow-up.
    const auto &STI = MI.getMF()->getSubtarget<MC6809Subtarget>();
    if (STI.has6309() && OpTy == LLT::scalar(32)) {
      auto RhsConst = getIConstantVRegValWithLookThrough(Rhs, MRI);
      if (RhsConst) {
        // Normalise the four equivalent shapes into a single "sign-bit
        // result + optional invert" pair.
        bool Invert = false;
        bool IsSignTest = false;
        if (RhsConst->Value == 0) {
          if (Pred == CmpInst::ICMP_SLT) { IsSignTest = true; Invert = false; }
          else if (Pred == CmpInst::ICMP_SGE) { IsSignTest = true; Invert = true; }
        } else if (RhsConst->Value.isAllOnes()) {
          if (Pred == CmpInst::ICMP_SLE) { IsSignTest = true; Invert = false; }
          else if (Pred == CmpInst::ICMP_SGT) { IsSignTest = true; Invert = true; }
        }
        if (IsSignTest) {
          // SignTest_i32 outputs an ACC8 with the byte's LSB carrying
          // the boolean.  Materialize via byte vreg + trunc to i1 for
          // the G_ICMP Dst; for Invert (sge X, 0 / sgt X, -1), XOR the
          // byte result with 1 before the trunc.
          LLT S1 = LLT::scalar(1);
          LLT S8 = LLT::scalar(8);
          MRI.setRegClass(Lhs, &MC6809::ACC32RegClass);
          Register SignByte = MRI.createGenericVirtualRegister(S8);
          MRI.setRegClass(SignByte, &MC6809::ACC8RegClass);
          B.buildInstr(MC6809::SignTest_i32, {SignByte}, {Lhs});
          MRI.setRegClass(Dst, &MC6809::ACC8RegClass);
          if (Invert) {
            auto OneB = B.buildConstant(S8, 1);
            auto XorB = B.buildXor(S8, SignByte, OneB);
            B.buildTrunc(Dst, XorB);
          } else {
            B.buildTrunc(Dst, SignByte);
          }
          MI.eraseFromParent();
          (void)S1;
          return true;
        }
        // Bug #301 (2026-05-16): equal-to-zero fast path.
        //   icmp eq X, 0  →  EqZero_i32 X
        //   icmp ne X, 0  →  XOR (EqZero_i32 X) 1
        // Lowers to a 4-byte OR-chain that sets CC.Z if all bytes were 0,
        // then materialises Z as a 0/1 byte.  Replaces __cmpsi2 + trunc +
        // icmp eq 0 for this very common shape.
        if (Pred == CmpInst::ICMP_EQ || Pred == CmpInst::ICMP_NE) {
          // EqZero_i32 / EqConst_i32 path.  Output is a 0/1 byte (ACC8)
          // truncated back to i1 for the G_ICMP Dst.  For NE we XOR
          // with 1 before the trunc.  K=0 routes to EqZero_i32 (OR-chain
          // + Z extraction); K!=0 routes to EqConst_i32 (SUBW+SBCD chain
          // + Z extraction).
          LLT S1 = LLT::scalar(1);
          LLT S8 = LLT::scalar(8);
          LLT S32 = LLT::scalar(32);
          MRI.setRegClass(Lhs, &MC6809::ACC32RegClass);
          bool InvertEq = (Pred == CmpInst::ICMP_NE);
          bool IsKZero = (RhsConst->Value == 0);
          Register IsEqByte = MRI.createGenericVirtualRegister(S8);
          MRI.setRegClass(IsEqByte, &MC6809::ACC8RegClass);
          if (IsKZero) {
            B.buildInstr(MC6809::EqZero_i32, {IsEqByte}, {Lhs});
          } else {
            // EqConst_i32 takes the i32 constant as an immediate operand.
            // buildInstr's {dst}/{src} variadic form doesn't accept
            // immediates, so use the explicit operand-by-operand form.
            int64_t KSigned = RhsConst->Value.getSExtValue();
            B.buildInstr(MC6809::EqConst_i32, {IsEqByte}, {})
                .addUse(Lhs)
                .addImm(KSigned);
          }
          // The byte already holds the 0/1 value; the trunc to i1
          // just narrows the LLT.  Dst is ACC8 (MVT::i1's class).
          if (InvertEq) {
            auto OneB = B.buildConstant(S8, 1);
            auto XorB = B.buildXor(S8, IsEqByte, OneB);
            MRI.setRegClass(Dst, &MC6809::ACC8RegClass);
            B.buildTrunc(Dst, XorB);
          } else {
            MRI.setRegClass(Dst, &MC6809::ACC8RegClass);
            B.buildTrunc(Dst, IsEqByte);
          }
          MI.eraseFromParent();
          (void)S1; (void)S32;
          return true;
        }
        // Bug #301 (2026-05-16): non-eq/ne i32 ICMP against constant
        // RHS, with a G_BRCOND-only consumer, lowers directly to the
        // fused CompareBranch_i32_Imm pseudo.  This is the most common
        // shape in libc (`if (X < K) ...`).
        //
        // Why fused-direct (not a separated compare + conditional-
        // branch pair)?  A previously-attempted design used a separated
        // Compare_i32_Imm (CCond output) + ConditionalImm pseudo that
        // broke 4 libc files: the CCond vreg gets DCE'd post-expansion
        // (LBlbc reads physregs, not the vreg), so the conditional
        // branch reads undef CC flags.  The fused pseudo is
        // isTerminator=true, can never be DCE'd as dead, and its
        // SUBW+SBCD+LB<cc> expansion is emitted contiguously — no
        // scheduler can wedge a flag-clobber between the SBCD and
        // the LB<cc>.
        //
        // Restricted to: HD6309, constant RHS, non-eq/ne (eq/ne use
        // EqZero_i32/EqConst_i32 above), exactly one use of the i1
        // Dst, that use is G_BRCOND in the same MBB.  Other shapes
        // fall through to libcall.
        unsigned CCImm = 0;
        bool MappedPred = true;
        switch (Pred) {
        case CmpInst::ICMP_SLT: CCImm = MC6809CC::LT; break;
        case CmpInst::ICMP_SLE: CCImm = MC6809CC::LE; break;
        case CmpInst::ICMP_SGT: CCImm = MC6809CC::GT; break;
        case CmpInst::ICMP_SGE: CCImm = MC6809CC::GE; break;
        case CmpInst::ICMP_ULT: CCImm = MC6809CC::LO; break;
        case CmpInst::ICMP_ULE: CCImm = MC6809CC::LS; break;
        case CmpInst::ICMP_UGT: CCImm = MC6809CC::HI; break;
        case CmpInst::ICMP_UGE: CCImm = MC6809CC::HS; break;
        default: MappedPred = false; break;
        }
        if (MappedPred && MRI.hasOneNonDBGUse(Dst)) {
          MachineInstr &UseMI = *MRI.use_instr_nodbg_begin(Dst);
          if (UseMI.getOpcode() == TargetOpcode::G_BRCOND &&
              UseMI.getParent() == MI.getParent()) {
            // Emit the fused CompareBranch_i32_Imm and erase both
            // G_ICMP and G_BRCOND.
            MachineBasicBlock *TgtMBB = UseMI.getOperand(1).getMBB();
            int64_t KSigned = RhsConst->Value.getSExtValue();
            MRI.setRegClass(Lhs, &MC6809::ACC32RegClass);
            // Insert before the G_BRCOND (which will be erased).
            B.setInsertPt(*UseMI.getParent(), UseMI);
            B.buildInstr(MC6809::CompareBranch_i32_Imm)
                .addImm(CCImm)
                .addUse(Lhs)
                .addImm(KSigned)
                .addMBB(TgtMBB);
            UseMI.eraseFromParent();
            MI.eraseFromParent();
            return true;
          }
        }
        // Bug #301 (2026-05-16): non-brcond consumer fallback.
        // When the fused-branch fast path above didn't fire (no
        // brcond-only consumer in same MBB), materialize the i1
        // result via the CompareSet_i8_i32_Imm fused compare-and-set
        // pseudo (X86 SETcc / AArch64 CSET / ARM MOVCC shape).
        // CompareSet emits SUBW + SBCD + per-predicate branch-free
        // CC bit extraction into a 0/1 byte in ACC8.  Single fused
        // MI — no cross-BB CCond live range, no DCE hazard.  Common
        // shapes that reach this path: G_STORE i1, G_TRUNC i1→byte,
        // G_AND/OR/XOR i1, G_ZEXT/SEXT i1→wider chains.
        if (MappedPred) {
          LLT S1 = LLT::scalar(1);
          LLT S8 = LLT::scalar(8);
          MRI.setRegClass(Lhs, &MC6809::ACC32RegClass);
          int64_t KSigned = RhsConst->Value.getSExtValue();
          Register ResultByte = MRI.createGenericVirtualRegister(S8);
          MRI.setRegClass(ResultByte, &MC6809::ACC8RegClass);
          B.buildInstr(MC6809::CompareSet_i8_i32_Imm, {ResultByte}, {})
              .addImm(CCImm)
              .addUse(Lhs)
              .addImm(KSigned);
          // The byte already holds the 0/1 value; trunc to i1 just
          // narrows the LLT.  Dst is ACC8 (MVT::i1's class).
          MRI.setRegClass(Dst, &MC6809::ACC8RegClass);
          B.buildTrunc(Dst, ResultByte);
          MI.eraseFromParent();
          (void)S1;
          return true;
        }
        // Bug #301 (2026-05-16): tripwire for the
        // "G_SELECT-consumer-that-escaped-the-GISel-combiner" case.
        // When the fused-branch fast path above didn't fire AND any
        // use of the i1 Dst is G_SELECT, this is a candidate for a
        // fused Select_i*_CC pseudo (X86 CMOV / ARM MOVCC /
        // AArch64 CSEL shape).  The 2026-05-16 probe found that
        // GISel's CombinerHelper converts every typical G_SELECT
        // shape (constants, loaded values, computed values) to
        // brcond+PHI BEFORE this legalizer runs (the fused-branch
        // path above then catches them), so the Select_i*_CC pseudo
        // was NOT implemented.  If this tripwire fires in a real
        // build, that pseudo IS needed after all.  Print a marker
        // that's grep-friendly in build logs and CI captures.
        if (MappedPred) {
          for (MachineInstr &U : MRI.use_nodbg_instructions(Dst)) {
            if (U.getOpcode() == TargetOpcode::G_SELECT) {
              static bool Warned = false;
              if (!Warned) {
                Warned = true;
                errs() << "MC6809-BUG-301-SELECT-CANDIDATE: i32 "
                       << "G_ICMP (non-eq/ne, constant RHS) with "
                       << "G_SELECT consumer that escaped the GISel "
                       << "combiner.  A fused Select_i*_CC pseudo "
                       << "(X86 CMOV / ARM MOVCC / AArch64 CSEL "
                       << "shape) was designed for this case but "
                       << "not implemented since the 2026-05-16 "
                       << "probe found no in-tree shapes that need "
                       << "it.  File a follow-up bug.\n";
              }
              break;
            }
          }
        }
      }
    }

    // i32/i64 compare via libcall to __{u,}cmp{s,d}i2 (bug #158).
    //
    // Inline compare at these widths decomposes into a multi-instruction
    // CC-setting sequence whose trailing conditional branch is exposed
    // to a regalloc race: the spill placer doesn't see CC as live across
    // the gap (the Compare pseudo carries the dep via a virtual CCond
    // output, not via physical CC reg Defs), so STY/LDY can land in the
    // middle and clobber CC.Z. A libcall collapses the whole sequence
    // into one LBSR, which IS a hard barrier for the spill placer —
    // closes the class of bugs by construction.
    //
    // compiler-rt ABI: __cmpXi2 and __ucmpXi2 return 0 if a<b, 1 if
    // a==b, 2 if a>b. We post-process with an i32 icmp against the
    // appropriate constant:
    //
    //    lt/ult   →  eq result, 0
    //    le/ule   →  ne result, 2
    //    gt/ugt   →  eq result, 2
    //    ge/uge   →  ne result, 0
    //    eq       →  eq result, 1
    //    ne       →  ne result, 1
    if (OpTy == LLT::scalar(32) || OpTy == LLT::scalar(64)) {
      bool IsUnsigned = CmpInst::isUnsigned(Pred) || Pred == CmpInst::ICMP_EQ ||
                        Pred == CmpInst::ICMP_NE;
      const char *Name;
      if (OpTy == LLT::scalar(32))
        Name = IsUnsigned ? "__ucmpsi2" : "__cmpsi2";
      else
        Name = IsUnsigned ? "__ucmpdi2" : "__cmpdi2";

      auto &Ctx = MI.getMF()->getFunction().getContext();
      Type *OpC = OpTy == LLT::scalar(32) ? (Type *)Type::getInt32Ty(Ctx)
                                          : (Type *)Type::getInt64Ty(Ctx);
      Type *RetC = Type::getInt32Ty(Ctx);  // compiler-rt cmpXi2 returns i32

      LLT Ret32 = LLT::scalar(32);
      Register Ret32Reg = MRI.createGenericVirtualRegister(Ret32);

      SmallVector<CallLowering::ArgInfo, 2> Args;
      Args.push_back({Lhs, OpC, 0});
      Args.push_back({Rhs, OpC, 1});
      if (!Helper.createLibcall(Name, {Ret32Reg, RetC, 0}, Args,
                                CallingConv::C, LocObserver))
        return false;

      // Post-call comparison on i8: the libcall result is always in
      // {0, 1, 2}, which fits in a byte. i8 avoids re-entering this same
      // custom rule (observed as a hang when I first tried i32 here, and
      // i16 would emit `cmpd #imm16` where only 8 bits are meaningful).
      // Comparing on i8 also opens up CompareBranch_i8_Imm fusion in
      // the selector's G_BRCOND case — the whole point of the libcall fix is to get a
      // single-MI compare→branch at the point where the result is
      // consumed.
      LLT Ret8 = LLT::scalar(8);
      auto Ret8Reg = B.buildTrunc(Ret8, Ret32Reg);

      // Map the original predicate to (newPred, compareConst) on Ret16Reg.
      CmpInst::Predicate NewPred;
      int64_t CmpVal;
      switch (Pred) {
      case CmpInst::ICMP_EQ:
        NewPred = CmpInst::ICMP_EQ; CmpVal = 1; break;
      case CmpInst::ICMP_NE:
        NewPred = CmpInst::ICMP_NE; CmpVal = 1; break;
      case CmpInst::ICMP_SLT:
      case CmpInst::ICMP_ULT:
        NewPred = CmpInst::ICMP_EQ; CmpVal = 0; break;
      case CmpInst::ICMP_SLE:
      case CmpInst::ICMP_ULE:
        NewPred = CmpInst::ICMP_NE; CmpVal = 2; break;
      case CmpInst::ICMP_SGT:
      case CmpInst::ICMP_UGT:
        NewPred = CmpInst::ICMP_EQ; CmpVal = 2; break;
      case CmpInst::ICMP_SGE:
      case CmpInst::ICMP_UGE:
        NewPred = CmpInst::ICMP_NE; CmpVal = 0; break;
      default:
        return false;
      }

      auto CmpConst = B.buildConstant(Ret8, CmpVal);
      B.buildICmp(NewPred, Dst, Ret8Reg, CmpConst);
      MI.eraseFromParent();
      return true;
    }

    // Unreachable — other widths should be covered by the legalForCartesianProduct
    // / clampScalar rules above.
    return false;
  }
  case G_ZEXT:
  case G_ANYEXT: {
    // Decompose s1→s16/s32/s64: zext s1→s8 (AND #1), then merge with zeros.
    // Can't chain G_ZEXT (combiner folds them → infinite loop).
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg = MI.getOperand(1).getReg();
    LLT DstTy = MRI.getType(DstReg);
    MachineIRBuilder &B = Helper.MIRBuilder;
    LLT S8 = LLT::scalar(8);
    auto Ext8 = B.buildZExt(S8, SrcReg);
    unsigned DstBytes = DstTy.getSizeInBytes();
    SmallVector<Register, 8> Parts;
    Parts.push_back(Ext8.getReg(0));
    for (unsigned I = 1; I < DstBytes; ++I)
      Parts.push_back(B.buildConstant(S8, 0).getReg(0));
    B.buildMergeValues(DstReg, Parts);
    MI.eraseFromParent();
    return true;
  }
  case G_TRUNC: {
    // s1 from s16: lower via an intermediate s8 trunc, since the
    // selector only has patterns for the s1-from-s8 trunc (which
    // becomes a single AND #1).
    //
    // The artifact combiner's `trunc(trunc) -> trunc` rule used to
    // refold this back into the original (s1, s16) trunc, causing
    // an infinite loop in the legalizer. The combiner now bails on
    // that fold when the resulting trunc has a customFor rule —
    // see the matching change in
    // include/llvm/CodeGen/GlobalISel/LegalizationArtifactCombiner.h.
    // Bug #243 (Class B): also handle (s1, s32) on HD6309. s32 reaches
    // here in __big_split (hash_bigkey.c) at -Og where loop-carried i32
    // collapses to s1 for a comparison. Chain s32 → s16 → s1.
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg = MI.getOperand(1).getReg();
    LLT DstTy = MRI.getType(DstReg);
    LLT SrcTy = MRI.getType(SrcReg);
    if (DstTy != LLT::scalar(1))
      return false;
    MachineIRBuilder &B = Helper.MIRBuilder;
    if (SrcTy == LLT::scalar(32)) {
      auto Tmp16 = B.buildTrunc(LLT::scalar(16), SrcReg);
      auto Tmp8 = B.buildTrunc(LLT::scalar(8), Tmp16);
      B.buildTrunc(DstReg, Tmp8);
      MI.eraseFromParent();
      return true;
    }
    if (SrcTy != LLT::scalar(16))
      return false;
    auto Tmp8 = B.buildTrunc(LLT::scalar(8), SrcReg);
    B.buildTrunc(DstReg, Tmp8);
    MI.eraseFromParent();
    return true;
  }
  case G_SEXT: {
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg = MI.getOperand(1).getReg();
    LLT DstTy = MRI.getType(DstReg);
    LLT SrcTy = MRI.getType(SrcReg);
    MachineIRBuilder &B = Helper.MIRBuilder;

    // (sN, s1) where N > 1: emit `select s1, -1, 0` at the destination
    // width. This is the MOS-proven pattern (MOSLegalizerInfo.cpp:596)
    // that completely avoids the chained-sext and upstream lowerEXT's
    // MERGE_VALUES(src, ASHR_HI) pattern. The select lowers via
    // MC6809LowerSelect into a branch + constant-materialization diamond,
    // which uses ONE i16 register (D) at any point — eliminating the
    // 5-simultaneous-vreg pressure spike that was bug #82b's root cause.
    // Surfaces in picolibc ftell.c / ftello.c.
    if (SrcTy == LLT::scalar(1)) {
      auto NegOne = B.buildConstant(DstTy, -1);
      auto Zero = B.buildConstant(DstTy, 0);
      B.buildSelect(DstReg, SrcReg, NegOne, Zero);
      MI.eraseFromParent();
      return true;
    }

    // Bug #282: G_SEXT (s64, s32) — byte-level lowering with the
    // sign-fill computation deliberately emitted AFTER any enclosing
    // ADJCALLSTACKUP.
    //
    // Surface: `sext i32-call-result to i64` in tiny wrappers like
    // picolibc test-math `test_lrint_zero`. IRTranslator places the
    // G_SEXT AFTER the call's ADJCALLSTACKUP — but combiner merges
    // G_LOAD + G_SEXT into G_SEXTLOAD at the G_LOAD's position
    // (INSIDE the call frame, because the sret slot must be read
    // before frame teardown). G_SEXTLOAD's legalizeLoad then splits
    // back into G_LOAD + G_SEXT at the inside-frame position, so my
    // G_SEXT custom inherits that position too.
    //
    // Multiple pitfalls compound when the G_SEXT lowering is emitted
    // inside the outer ADJCALLSTACK pair:
    //   1. G_ICMP s32 → `__cmpsi2` libcall (custom rule at line
    //      ~613) — nests an inner ADJCALLSTACK pair (verifier:
    //      "FrameSetup is after another FrameSetup").
    //   2. G_ICMP s8 → i1 vreg materialised via PHI of Load_i1_Imm-
    //      0/1 in a branch diamond — splits the BB so the outer
    //      ADJCALLSTACK pair spans multiple BBs (verifier: "Call
    //      frame size on entry does not match value computed from
    //      predecessor"). The phantom-carry fast path cannot reliably
    //      avoid this when consumer ordering forces materialization.
    //   3. G_ASHR s8 by 7 widens via shouldOverCorrect to s16, which
    //      then routes to `__ashlhi3` + `__lshrhi3` libcalls —
    //      Pitfall 1 family.
    //
    // Fix: walk forward from MI looking for the enclosing
    // ADJCALLSTACKUP (the call's frame teardown). If found, set the
    // MIRBuilder insertion point to AFTER it before emitting the
    // sign-derive sequence and the final merge. This re-establishes
    // the IRTranslator's original position for the G_SEXT (= outside
    // the frame), where the i1 diamond materialization is harmless
    // and any libcall would be properly sequenced.
    //
    // The sign-fill itself: `0 - zext(slt(MSB, 0))`. Each component
    // is single-MI native MC6809:
    //   - G_ICMP slt(s8,s8) → CMPB + Bcc (legal per
    //     legalForCartesianProduct({s1}, {s8, s16})).
    //   - G_ZEXT s8←s1 → MaterializeCC_C_to_byte (phantom-carry
    //     fast path) OR the AND_i8_Imm tied fallback for real-byte i1.
    //   - G_SUB s8 → SUBB / SUBA.
    if (DstTy == LLT::scalar(64) && SrcTy == LLT::scalar(32)) {
      LLT S1 = LLT::scalar(1);
      LLT S8 = LLT::scalar(8);

      // Walk forward looking for the enclosing ADJCALLSTACKUP. If
      // found AND no use of DstReg appears before it, override the
      // MIRBuilder insertion point to AFTER it. The use-presence
      // check distinguishes:
      //   - `sext i32-call-result to i64` consumed by a sret store
      //     OUTSIDE the call frame (test_lrint_zero shape): move
      //     past ADJCALLSTACKUP so the diamond doesn't split the
      //     frame.
      //   - `sext i32 to i64` consumed by argument stores for a
      //     later libcall like __ucmpdi2 INSIDE the same frame
      //     (eq_i64_sext_i32 shape): the SEXT's result must be
      //     ready before the stores; moving past ADJCALLSTACKUP
      //     would orphan those stores from the SEXT's defs.
      // Otherwise leave the default insertion point (BEFORE MI) in
      // place.
      MachineBasicBlock &MBB = *MI.getParent();
      unsigned FrameDestroyOpc = B.getTII().getCallFrameDestroyOpcode();
      MachineBasicBlock::iterator FrameUp = MBB.end();
      for (auto It = std::next(MI.getIterator()); It != MBB.end(); ++It) {
        if (It->getOpcode() == FrameDestroyOpc) {
          FrameUp = It;
          break;
        }
      }
      bool UseBeforeFrameUp = false;
      if (FrameUp != MBB.end()) {
        for (const MachineInstr &User : MRI.use_instructions(DstReg)) {
          if (User.getParent() != &MBB)
            continue;  // Cross-MBB uses are naturally after FrameUp.
          for (auto It = std::next(MI.getIterator()); It != FrameUp; ++It) {
            if (&*It == &User) {
              UseBeforeFrameUp = true;
              break;
            }
          }
          if (UseBeforeFrameUp)
            break;
        }
      }
      if (FrameUp != MBB.end() && !UseBeforeFrameUp)
        B.setInsertPt(MBB, std::next(FrameUp));

      auto Unmerge = B.buildUnmerge(S8, SrcReg);
      SmallVector<Register, 8> Bytes;
      for (unsigned I = 0; I < 4; ++I)
        Bytes.push_back(Unmerge.getReg(I));
      auto Zero = B.buildConstant(S8, 0);
      auto SignI1 = B.buildICmp(CmpInst::ICMP_SLT, S1, Bytes.back(), Zero);
      auto SignByte = B.buildZExt(S8, SignI1);
      Register Fill = B.buildSub(S8, Zero, SignByte).getReg(0);
      while (Bytes.size() < 8)
        Bytes.push_back(Fill);
      B.buildMergeLikeInstr(DstReg, Bytes);
      MI.eraseFromParent();
      return true;
    }

    return false;
  }
  case G_SELECT: {
    // Decompose wide select into pairs of half-width selects.
    // i32 → 2×i16, i64 → 2×i32 (each i32 re-enters and splits to 2×i16).
    // Use separate copies of the condition register so that the
    // MC6809LowerSelect pass doesn't merge them into one diamond
    // (which would put multiple ACC16 loads in the same block → regalloc fail).
    Register DstReg = MI.getOperand(0).getReg();
    Register CondReg = MI.getOperand(1).getReg();
    Register TrueReg = MI.getOperand(2).getReg();
    Register FalseReg = MI.getOperand(3).getReg();
    MachineIRBuilder &B = Helper.MIRBuilder;
    LLT DstTy = MRI.getType(DstReg);
    LLT S1 = LLT::scalar(1);
    LLT HalfTy = LLT::scalar(DstTy.getSizeInBits() / 2);
    auto TrueParts = B.buildUnmerge(HalfTy, TrueReg);
    auto FalseParts = B.buildUnmerge(HalfTy, FalseReg);
    auto CondLo = B.buildCopy(S1, CondReg);
    auto CondHi = B.buildCopy(S1, CondReg);
    auto SelLo = B.buildSelect(HalfTy, CondLo,
        TrueParts.getReg(0), FalseParts.getReg(0));
    auto SelHi = B.buildSelect(HalfTy, CondHi,
        TrueParts.getReg(1), FalseParts.getReg(1));
    B.buildMergeValues(DstReg, {SelLo.getReg(0), SelHi.getReg(0)});
    MI.eraseFromParent();
    return true;
  }
  case G_EXTRACT:
  case G_INSERT:
    return legalizeExtractInsert(Helper, MRI, MI, LocObserver);
  case G_FCONSTANT:
    return legalizeFConstant(Helper, MRI, MI, LocObserver);
  case G_PTR_ADD: {
    // Direct-page (p1) pointer add. A __directpage object lives wholly within
    // the 256-byte page, so an in-page index never crosses it: do the address
    // arithmetic in 8 bits and keep the result p1. G_PTRTOINT(p1)->s8 and
    // G_INTTOPTR(s8)->p1 are legal (equal-size), and an 8-bit G_ADD is legal.
    Register DstReg = MI.getOperand(0).getReg();
    Register BaseReg = MI.getOperand(1).getReg();
    Register OffReg = MI.getOperand(2).getReg();
    MachineIRBuilder &B = Helper.MIRBuilder;
    LLT S8 = LLT::scalar(8);
    auto Base8 = B.buildPtrToInt(S8, BaseReg);
    auto Off8 = B.buildTrunc(S8, OffReg);
    auto Sum8 = B.buildAdd(S8, Base8, Off8);
    B.buildIntToPtr(DstReg, Sum8);
    MI.eraseFromParent();
    return true;
  }
  case G_PTRMASK: {
    // Decompose G_PTRMASK (p0, s16) → PTRTOINT + AND + INTTOPTR.
    Register DstReg = MI.getOperand(0).getReg();
    Register PtrReg = MI.getOperand(1).getReg();
    Register MaskReg = MI.getOperand(2).getReg();
    MachineIRBuilder &B = Helper.MIRBuilder;
    LLT MaskTy = MRI.getType(MaskReg);
    auto AsInt = B.buildPtrToInt(MaskTy, PtrReg);
    auto Masked = B.buildAnd(MaskTy, AsInt, MaskReg);
    B.buildIntToPtr(DstReg, Masked);
    MI.eraseFromParent();
    return true;
  }
  case G_VASTART:
    return legalizeVAStart(Helper, MRI, MI, LocObserver);
  case G_VAARG:
    return legalizeVAArg(Helper, MRI, MI, LocObserver);
  case G_LSHR:
  case G_SHL:
  case G_ASHR:
  case G_ROTL:
  case G_ROTR:
    return legalizeShiftRotate(Helper, MRI, MI, LocObserver);
  case G_FSHL:
  case G_FSHR:
    return legalizeFunnelShift(Helper, MRI, MI, LocObserver);
  case G_UMULO:
    return legalizeMultiplyWithOverflow(Helper, MRI, MI, LocObserver);
  case G_SMULFIX:
  case G_UMULFIX:
  case G_SMULFIXSAT:
  case G_UMULFIXSAT:
    return legalizeFixedMultiply(Helper, MRI, MI, LocObserver);
  case G_SDIVFIX:
  case G_UDIVFIX:
  case G_SDIVFIXSAT:
  case G_UDIVFIXSAT:
    return legalizeFixedDivide(Helper, MRI, MI, LocObserver);
  case G_FCANONICALIZE:
    return legalizeFCanonicalize(Helper, MRI, MI, LocObserver);
    break;
  case G_ABS: {
    // |x| via two's complement negation, then SELECT on the sign bit.
    //
    // Lowering produced:
    //   %not = G_XOR %src, -1     ; bitwise NOT (each byte XORed with 0xFF)
    //   %neg = G_ADD %not, 1      ; ~x + 1 == -x  (two's complement identity)
    //   %cmp = G_ICMP slt, %src, 0
    //   %res = G_SELECT %cmp, %neg, %src
    //
    // Math: for any signed integer x in two's complement,
    //   -x = ~x + 1
    // So  abs(x) = (x < 0) ? -x : x
    //            = (x < 0) ? (~x + 1) : x
    //
    // Why this lowering instead of the obvious (G_SUB 0, %src)?
    // -----------------------------------------------------------
    // Bug #61: GISel's selectSubO/selectSubE in
    // MC6809InstructionSelector.cpp had a bug where the (const, reg)
    // matchers silently swapped operands when emitting
    // SubSetCarry_*_Imm — computing "x - 0" (no-op) instead of
    // "0 - x" (negation). The bug is now FIXED in selectSubO/E
    // proper, but going through XOR + ADD here keeps a small code
    // quality win: it avoids loading the 0-constant into a vreg
    // (which the (reg, reg) sub path requires) and produces a
    // tighter sequence on 6809.
    //
    // Why not the default LegalizerHelper ABS lowering?
    // -------------------------------------------------
    // The LLVM default does (x ^ (x ASHR (N-1))) - (x ASHR (N-1)),
    // which also avoids SUB(0, x) but requires an arithmetic shift
    // by 31 of the i32 input. ASHR i32 has no native instruction on
    // the 6809 — it would expand to a tower of byte shifts (or a
    // libcall on top of that), one or two orders of magnitude
    // larger than this XOR + ADD pair.
    //
    // XOR with all-ones is genuinely tight on the 6809: two byte-XORs
    // against the immediate 0xFF (one per A/B half) for i16, four
    // for i32. ADD with 1 is a single ADDD #1 (i16) or two i16 adds
    // chained via carry (i32). Both narrow naturally without
    // exposing #61's bug or the older multi-spill pattern (#63).
    MachineIRBuilder &Builder = Helper.MIRBuilder;
    Register Dst = MI.getOperand(0).getReg();
    Register Src = MI.getOperand(1).getReg();
    LLT Ty = MRI.getType(Src);
    // Step 1: ~src  (each byte XORed with 0xFF; the i32 narrows to
    //                two i16 XORs which narrow further to four i8 XORs).
    auto NegOne = Builder.buildConstant(Ty, -1);
    auto NotSrc = Builder.buildXor(Ty, Src, NegOne);
    // Step 2: ~src + 1  (two's complement of src, == -src).
    auto One = Builder.buildConstant(Ty, 1);
    auto Neg = Builder.buildAdd(Ty, NotSrc, One);
    // Step 3: pick -src for negative inputs, src for non-negative.
    auto Zero = Builder.buildConstant(Ty, 0);
    auto Cmp = Builder.buildICmp(CmpInst::ICMP_SLT, LLT::scalar(1), Src, Zero);
    Builder.buildSelect(Dst, Cmp, Neg, Src);
    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }
  case G_MEMCPY:
  case G_MEMCPY_INLINE:
  case G_MEMMOVE:
  case G_MEMSET:
    return legalizeMemOp(Helper, MRI, MI, LocObserver);
  }
  return false;
}


bool
MC6809LegalizerInfo::legalizeBitwise(LegalizerHelper &Helper,
    MachineRegisterInfo &MRI, MachineInstr &MI,
    LostDebugLocObserver &LocObserver) const {
  unsigned Opc = MI.getOpcode();
  assert((Opc == G_AND || Opc == G_OR || Opc == G_XOR) && "Unexpected opcode");
  MachineIRBuilder &B = Helper.MIRBuilder;
  LLT Ty = MRI.getType(MI.getOperand(0).getReg());

  // s1 G_AND/G_OR/G_XOR lowers to
  //    trunc(<op>(anyext(a, s8), anyext(b, s8)), s1).
  // MC6809 has no native 1-bit bitwise op; do it at byte width and
  // truncate the result back.
  //
  // Use ANYEXT (not ZEXT).  For carry-phantom s1 sources the byte's
  // LSB the regalloc allocated is unrelated to the real value (which
  // lives in CC.C), and ZEXT would mask off the wrong byte.  ANYEXT
  // routes through the selector's G_ANYEXT s1→s8 custom path which
  // detects carry-phantom sources and materialises CC.C → 0/1 byte
  // (LDB #0 ; ADCB #0).  For real-byte i1 sources the path is a
  // plain COPY — upper bits are garbage but the final G_TRUNC
  // discards them.
  if (Ty == LLT::scalar(1)) {
    Register Dst = MI.getOperand(0).getReg();
    Register A   = MI.getOperand(1).getReg();
    Register B2  = MI.getOperand(2).getReg();
    LLT S8 = LLT::scalar(8);
    auto AExt = B.buildAnyExt(S8, A);
    auto BExt = B.buildAnyExt(S8, B2);
    auto Op8  = B.buildInstr(Opc, {S8}, {AExt, BExt});
    B.buildTrunc(Dst, Op8);
    MI.eraseFromParent();
    return true;
  }

  assert(Ty == LLT::scalar(32) && "Expected s1 or s32");

  // Bug #210 round 5 (2026-05-04): route i32 G_AND/G_OR/G_XOR to libcalls
  // (`__andsi3`/`__orsi3`/`__xorsi3` — implemented in compiler-rt).
  // The previous in-line decomposition (legalizeI32BinaryOp) emitted
  // G_UNMERGE_VALUES + 2x i16 op + G_MERGE_VALUES, which the selector
  // turned into EXTRACT/sub-reg-write artifacts that synth-collapse the
  // parent vreg to aqc (1 register). Hash.c's __call_hash had 7 such
  // aqc vregs from i32 mask AND chains — same starvation as the load
  // pattern Round 5 fixed earlier. Routing to a libcall pushes the
  // i32 work entirely outside the function; no in-line decomposition,
  // no aqc vregs, no starvation.
  Register DstReg = MI.getOperand(0).getReg();
  Register Lhs = MI.getOperand(1).getReg();
  Register Rhs = MI.getOperand(2).getReg();
  auto &Ctx = MI.getMF()->getFunction().getContext();
  Type *I32Ty = Type::getInt32Ty(Ctx);
  const char *Name = (Opc == G_AND) ? "__andsi3"
                   : (Opc == G_OR)  ? "__orsi3"
                                    : "__xorsi3";
  SmallVector<CallLowering::ArgInfo, 2> Args;
  Args.push_back({Lhs, I32Ty, 0});
  Args.push_back({Rhs, I32Ty, 1});
  if (!Helper.createLibcall(Name, {DstReg, I32Ty, 0}, Args,
                            CallingConv::C, LocObserver))
    return false;
  MI.eraseFromParent();
  return true;
}

bool MC6809LegalizerInfo::legalizeExtractInsert(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  assert((MI.getOpcode() == G_EXTRACT || MI.getOpcode() == G_INSERT) && "Unexpected opcode");
  return MI.getOperand(MI.getNumExplicitOperands() - 1).getImm() & 7 ? LegalizerHelper::UnableToLegalize : LegalizerHelper::Legalized;
}

bool MC6809LegalizerInfo::legalizeFConstant(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  assert(MI.getOpcode() == G_FCONSTANT && "Unexpected opcode");
  // Rewrite G_FCONSTANT into an integer G_CONSTANT carrying the bit
  // pattern of the FP value. The original code mutated the opcode in
  // place and called ChangeToImmediate, which sets an Imm operand —
  // but G_CONSTANT's operand must be a CImm (ConstantInt*), and
  // downstream narrow/widen helpers crash calling getCImm() on a
  // plain Imm. Build a fresh G_CONSTANT via MIRBuilder instead so the
  // operand kind is correct, and retype the destination register to
  // the matching integer LLT.
  MachineIRBuilder &B = Helper.MIRBuilder;
  Register DstReg = MI.getOperand(0).getReg();
  LLT DstTy = MRI.getType(DstReg);
  const ConstantFP *FPImm = MI.getOperand(1).getFPImm();
  const APInt AsInt = FPImm->getValueAPF().bitcastToAPInt();
  LLT IntTy = LLT::scalar(DstTy.getSizeInBits());
  MRI.setType(DstReg, IntTy);
  LLVMContext &Ctx = B.getMF().getFunction().getContext();
  B.setInstrAndDebugLoc(MI);
  B.buildConstant(DstReg, *ConstantInt::get(Ctx, AsInt));
  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

// Lower variable argument pointer setup intrinsic.
bool MC6809LegalizerInfo::legalizeVAStart(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  LLT P = LLT::pointer(0, 16);

  // Store the address of the fake varargs frame index into the valist.
  MachineIRBuilder &Builder = Helper.MIRBuilder;
  auto *FuncInfo = Builder.getMF().getInfo<MC6809FunctionInfo>();
  Builder.buildStore(Builder.buildFrameIndex(P, FuncInfo->VarArgsStackIndex), MI.getOperand(0), **MI.memoperands_begin());
  MI.eraseFromParent();
  return true;
}

bool MC6809LegalizerInfo::legalizeVAArg(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  // G_VAARG: %val = G_VAARG %ap_ptr, align
  // Decompose to: load current ap, bump+store ap, then load the value.
  //   ap_val = load ap_ptr       ; current va_list pointer
  //   ap_val += sizeof(type)     ; advance (always rounded up to 2 bytes)
  //   store ap_val to ap_ptr     ; write back
  //   val = load ap_val          ; load the argument LAST
  // Loading val LAST keeps DstReg's live range short and disjoint from the
  // store-back temporaries — otherwise regalloc can clobber DstReg with the
  // bumped ap (see picolibc bug #126b: %s in vfprintf miscompiled because
  // X held both the loaded char* arg and the new ap).
  MachineIRBuilder &Builder = Helper.MIRBuilder;
  LLT ValTy = MRI.getType(MI.getOperand(0).getReg());
  LLT P = LLT::pointer(0, 16);

  Register DstReg = MI.getOperand(0).getReg();
  Register APPtr = MI.getOperand(1).getReg();
  unsigned ArgSize = ValTy.getSizeInBytes();
  if (ArgSize < 2) ArgSize = 2; // 6809 CC: args are at least 16-bit aligned

  // Load current ap value (pointer to next vararg)
  auto APVal = Builder.buildLoad(P, APPtr, MachinePointerInfo(), Align(1));

  // Bump ap past this argument
  auto Bump = Builder.buildConstant(LLT::scalar(16), ArgSize);
  auto NewAP = Builder.buildPtrAdd(P, APVal, Bump);

  // Store updated ap back
  Builder.buildStore(NewAP, APPtr, MachinePointerInfo(), Align(1));

  // Load the argument value LAST — DstReg is now live only forward to its
  // consumer, so regalloc won't reuse its register for store-back temps.
  Builder.buildLoad(DstReg, APVal, MachinePointerInfo(), Align(1));

  MI.eraseFromParent();
  return true;
}

bool MC6809LegalizerInfo::legalizeFunnelShift(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  unsigned Opc = MI.getOpcode();
  assert((Opc == G_FSHL || Opc == G_FSHR || Opc == G_ROTR || Opc == G_ROTL) && "Unexpected opcode");

  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;

  Register DstReg = MI.getOperand(0).getReg();
  Register FwdReg = MI.getOperand(1).getReg();
  Register RevReg = MI.getOperand(MI.getNumExplicitOperands() - 2).getReg();
  Register AmtReg = MI.getOperand(MI.getNumExplicitOperands() - 1).getReg();

  LLT Ty = MRI.getType(DstReg);
  if (Ty == LLT::scalar(8))
    if (auto Amt = getIConstantVRegValWithLookThrough(AmtReg, MRI))
      return LegalizerHelper::AlreadyLegal;

  unsigned FwdShiftOpc = G_SHL;
  unsigned RevShiftOpc = G_LSHR;
  if (Opc == G_FSHR || Opc == G_ROTR) {
    std::swap(FwdReg, RevReg);
    std::swap(FwdShiftOpc, RevShiftOpc);
  }

  auto MaskI = MIRBuilder.buildConstant(Ty, Ty.getSizeInBits() - 1);
  auto FwdAmtI = MIRBuilder.buildAnd(Ty, AmtReg, MaskI);
  auto FwdI = MIRBuilder.buildInstr(FwdShiftOpc, {Ty}, {FwdReg, FwdAmtI});
  auto RevAmtI = MIRBuilder.buildAnd(Ty, MIRBuilder.buildSub(Ty, MIRBuilder.buildConstant(Ty, 0), AmtReg), MaskI);
  auto RevI = MIRBuilder.buildInstr(RevShiftOpc, {Ty}, {RevReg, RevAmtI});
  MIRBuilder.buildOr(DstReg, FwdI, RevI);
  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

bool MC6809LegalizerInfo::legalizeFixedMultiply(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;

  unsigned Opc = MI.getOpcode();
  bool Signed = Opc == G_SMULFIX || Opc == G_SMULFIXSAT;
  bool Sat = Opc == G_SMULFIXSAT || Opc == G_UMULFIXSAT;
  assert((Signed || Sat || Opc == G_UMULFIX) && "Unexpected opcode");

  Register DstReg = MI.getOperand(0).getReg();
  unsigned OpSize = MRI.getType(DstReg).getSizeInBits();
  Register LHSReg = MI.getOperand(1).getReg();
  Register RHSReg = MI.getOperand(2).getReg();
  uint64_t Shift = MI.getOperand(3).getImm();
  unsigned WideSize = OpSize * 2;
  LLT WideTy = LLT::scalar(WideSize);

  if (Shift >= WideSize)
    return LegalizerHelper::UnableToLegalize;

  Register WideDstReg = MIRBuilder
                            .buildInstr(Signed ? G_ASHR : G_LSHR, {WideTy},
                                        {MIRBuilder.buildMul(WideTy, MIRBuilder.buildInstr(Signed ? G_SEXT : G_ZEXT, {WideTy}, {LHSReg}), MIRBuilder.buildInstr(Signed ? G_SEXT : G_ZEXT, {WideTy}, {RHSReg})), MIRBuilder.buildConstant(WideTy, Shift)})
                            .getReg(0);
  if (Sat) {
    unsigned MinOpc;
    APInt Max;
    if (Signed) {
      WideDstReg = MIRBuilder.buildSMax(WideTy, WideDstReg, MIRBuilder.buildConstant(WideTy, APInt::getSignedMinValue(OpSize).sext(WideSize))).getReg(0);
      MinOpc = G_SMIN;
      Max = APInt::getSignedMaxValue(OpSize).sext(WideSize);
    } else {
      MinOpc = G_UMIN;
      Max = APInt::getMaxValue(OpSize).zext(WideSize);
    }
    WideDstReg = MIRBuilder.buildInstr(MinOpc, {WideTy}, {WideDstReg, MIRBuilder.buildConstant(WideTy, Max)}).getReg(0);
  }
  MIRBuilder.buildTrunc(DstReg, WideDstReg);

  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

bool MC6809LegalizerInfo::legalizeFixedDivide(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;

  unsigned Opc = MI.getOpcode();
  bool Signed = Opc == G_SDIVFIX || Opc == G_SDIVFIXSAT;
  bool Sat = Opc == G_SDIVFIXSAT || Opc == G_UDIVFIXSAT;
  assert((Signed || Sat || Opc == G_UDIVFIX) && "Unexpected opcode");

  Register DstReg = MI.getOperand(0).getReg();
  LLT OpTy = MRI.getType(DstReg);
  unsigned OpSize = OpTy.getSizeInBits();
  Register LHSReg = MI.getOperand(1).getReg();
  Register RHSReg = MI.getOperand(2).getReg();
  uint64_t Shift = MI.getOperand(3).getImm();
  unsigned WideSize = OpSize * 2;
  LLT WideTy = LLT::scalar(WideSize);

  if (Shift > 0 && Shift <= OpSize / 2 && WideSize > 64) {
    // FIXME: accuracy
    auto DivRemI = MIRBuilder.buildInstr(Signed ? G_SDIVREM : G_UDIVREM, {OpTy, OpTy}, {LHSReg, RHSReg});
    Register PosReg = DivRemI.getReg(1);
    if (Signed)
      PosReg = MIRBuilder.buildXor(OpTy, PosReg, MIRBuilder.buildAShr(OpTy, PosReg, MIRBuilder.buildConstant(OpTy, OpSize - 1))).getReg(0);
    Register ScaleReg = MIRBuilder
                            .buildSelect(OpTy, MIRBuilder.buildICmp(CmpInst::ICMP_ULT, LLT::scalar(1), PosReg, MIRBuilder.buildConstant(OpTy, APInt::getOneBitSet(OpSize, Shift - Signed))), MIRBuilder.buildConstant(OpTy, Shift - Signed),
                                         MIRBuilder.buildAdd(OpTy, MIRBuilder.buildInstr(G_CTLZ_ZERO_UNDEF, {OpTy}, {PosReg}), MIRBuilder.buildConstant(OpTy, -Signed)))
                            .getReg(0);
    Register ShiftReg = MIRBuilder.buildConstant(OpTy, Shift).getReg(0);
    Register InvScaleReg = MIRBuilder.buildSub(OpTy, ShiftReg, ScaleReg).getReg(0);
    Register OneReg = MIRBuilder.buildConstant(OpTy, 1).getReg(0);
    MIRBuilder.buildAdd(DstReg, MIRBuilder.buildShl(OpTy, DivRemI.getReg(0), ShiftReg),
                        MIRBuilder.buildInstr(Signed ? G_ASHR : G_LSHR, {OpTy},
                                              {MIRBuilder.buildInstr(Signed ? G_SDIV : G_UDIV, {OpTy},
                                                                     {MIRBuilder.buildShl(OpTy, DivRemI.getReg(1), ScaleReg), MIRBuilder.buildAdd(OpTy, RHSReg, MIRBuilder.buildLShr(OpTy, MIRBuilder.buildShl(OpTy, OneReg, InvScaleReg), OneReg))}),
                                               InvScaleReg}));
    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }

  if (Shift >= WideSize)
    return LegalizerHelper::UnableToLegalize;

  Register WideDstReg = MIRBuilder
                            .buildInstr(Signed ? G_SDIV : G_UDIV, {WideTy},
                                        {MIRBuilder.buildShl(WideTy, MIRBuilder.buildInstr(Signed ? G_SEXT : G_ZEXT, {WideTy}, {LHSReg}), MIRBuilder.buildConstant(WideTy, Shift)), MIRBuilder.buildInstr(Signed ? G_SEXT : G_ZEXT, {WideTy}, {RHSReg})})
                            .getReg(0);
  if (Sat) {
    unsigned MinOpc;
    APInt Max;
    if (Signed) {
      WideDstReg = MIRBuilder.buildSMax(WideTy, WideDstReg, MIRBuilder.buildConstant(WideTy, APInt::getSignedMinValue(OpSize).sext(WideSize))).getReg(0);
      MinOpc = G_SMIN;
      Max = APInt::getSignedMaxValue(OpSize).sext(WideSize);
    } else {
      MinOpc = G_UMIN;
      Max = APInt::getMaxValue(OpSize).zext(WideSize);
    }
    WideDstReg = MIRBuilder.buildInstr(MinOpc, {WideTy}, {WideDstReg, MIRBuilder.buildConstant(WideTy, Max)}).getReg(0);
  }
  MIRBuilder.buildTrunc(DstReg, WideDstReg);

  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

bool MC6809LegalizerInfo::legalizeMultiplyWithOverflow(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;

  assert(MI.getOpcode() == G_UMULO && "Unexpected opcode");

  Register MulReg = MI.getOperand(0).getReg();
  Register OverflowReg = MI.getOperand(1).getReg();
  LLT Ty = MRI.getType(MulReg);

  Register LHSReg = MI.getOperand(2).getReg();
  Register RHSReg = MI.getOperand(3).getReg();

  if (Ty == LLT::scalar(64)) {
    // Bug #239: i64 G_UMULO inline-decomposed into G_MUL + G_UDIV +
    // G_UMAX + G_ICMP exhausts the 5-slot ACC32 register class on
    // HD6309 -O2/-Og — strtoull / strtoumax / mktime_utc all fail
    // regalloc. Route to compiler-rt's __umulodi4 (fused 64x64 -> 128
    // schoolbook with overflow detection on the high half), so the
    // intermediate i64 vregs live inside the library frame and never
    // reach the caller's regalloc.
    //
    // C signature of __umulodi4:
    //   uint64_t __umulodi4(uint64_t a, uint64_t b, int *overflow);
    // returning the low 64 bits via sret-IX and writing the overflow
    // flag (0 or 1) through the int* arg.
    MachineFunction &MF = *MI.getMF();
    auto &Ctx = MF.getFunction().getContext();
    const DataLayout &DL = MIRBuilder.getDataLayout();
    unsigned AddrSpace = DL.getAllocaAddrSpace();

    // Allocate a stack temporary for the overflow flag. MC6809 'int'
    // is 16 bits; the runtime writes both bytes via STD. Load back as
    // s16 then truncate to s1 (= OverflowReg's expected type).
    LLT TempLLT = LLT::scalar(16);
    int MemSize = TempLLT.getSizeInBytes();
    Align Alignment = Helper.getStackTemporaryAlignment(TempLLT);
    MachinePointerInfo PtrInfo;
    Register StackPtrOf =
        Helper.createStackTemporary(TypeSize::getFixed(MemSize), Alignment,
                                    PtrInfo).getReg(0);

    Type *I64Ty = Type::getInt64Ty(Ctx);
    auto LibcallResult = Helper.createLibcall(
        "__umulodi4",
        {MulReg, I64Ty, 0},
        {{LHSReg, I64Ty, 0},
         {RHSReg, I64Ty, 1},
         {StackPtrOf, PointerType::get(Ctx, AddrSpace), 2}},
        CallingConv::C, LocObserver, &MI);

    if (LibcallResult != LegalizerHelper::Legalized)
      return false;

    // Load the overflow flag back as i16, truncate to s1.
    MachineMemOperand *LoadMMO = MF.getMachineMemOperand(
        PtrInfo, MachineMemOperand::MOLoad, MemSize, Alignment);
    auto LoadedOf16 = MIRBuilder.buildLoad(TempLLT, StackPtrOf, *LoadMMO);
    MIRBuilder.buildTrunc(OverflowReg, LoadedOf16);

    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }

  // s8 / s16 / s32 — keep the existing inline 4-op decomposition.
  // Those widths fit comfortably in ACC8 / ACC16; the regalloc
  // pressure problem is i64-specific.
  MIRBuilder.buildMul(MulReg, LHSReg, RHSReg);

  auto One = MIRBuilder.buildConstant(Ty, 1);
  auto Max = MIRBuilder.buildConstant(Ty, APInt::getMaxValue(Ty.getSizeInBits()));
  MIRBuilder.buildICmp(CmpInst::ICMP_UGT, OverflowReg, LHSReg, MIRBuilder.buildInstr(G_UDIV, {Ty}, {Max, MIRBuilder.buildUMax(Ty, RHSReg, One)}));

  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

bool MC6809LegalizerInfo::legalizeFCanonicalize(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  Helper.Observer.changingInstr(MI);
  MI.setDesc(Helper.MIRBuilder.getTII().get(COPY));
  Helper.Observer.changedInstr(MI);
  return LegalizerHelper::Legalized;
}

bool MC6809LegalizerInfo::legalizeMemOp(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  MachineIRBuilder &Builder = Helper.MIRBuilder;
  const MC6809Subtarget &STI = Builder.getMF().getSubtarget<MC6809Subtarget>();

  // Special handling for HD6309 block copy extensions.
  if (STI.has6309())
    if (tryTFMBlockCopy(Helper, MRI, MI))
      return true;

  bool IsSet = MI.getOpcode() == MC6809::G_MEMSET;
  bool IsInline = MI.getOpcode() == MC6809::G_MEMCPY_INLINE;

  // Bug #276: G_MEM{CPY,SET,MOVE} sitting between an ADJCALLSTACKDOWN
  // and its matching ADJCALLSTACKUP cannot legalize to a libcall — the
  // libcall would emit its own nested ADJCALLSTACK pair and LLVM's
  // MachineVerifier rejects nested call-frame setups (see
  // MachineVerifier::verifyStackFrame). Detect that case and emit a
  // hand-rolled byte-by-byte inline copy/set/move, bypassing
  // LegalizerHelper::findGISelOptimalMemOpLowering (which defers to
  // MaxStoresPerMemcpy + allowsMisalignedMemoryAccesses and rejects
  // common shapes at -Og + align=1).
  //
  // Typical surface: byval struct args at IR level whose copy ends up
  // > SizeLimit. CallLowering wraps the G_MEMCPY in the outer call's
  // ADJCALLSTACKDOWN/UP so $ss is valid as the dst base; the memop
  // must therefore stay inline.
  bool InsideCallFrame = false;
  {
    const MachineBasicBlock *MBB = MI.getParent();
    int FrameSetupOpc =
        Builder.getMF().getSubtarget().getInstrInfo()->getCallFrameSetupOpcode();
    int FrameDestroyOpc =
        Builder.getMF().getSubtarget().getInstrInfo()->getCallFrameDestroyOpcode();
    for (auto It = MachineBasicBlock::const_reverse_iterator(MI);
         It != MBB->rend(); ++It) {
      if ((int)It->getOpcode() == FrameDestroyOpc) {
        // A matched DOWN/UP pair before us — not inside.
        break;
      }
      if ((int)It->getOpcode() == FrameSetupOpc) {
        InsideCallFrame = true;
        break;
      }
    }
  }
  if (InsideCallFrame && !IsInline) {
    // Constant-length only (variable-length would need a hardware
    // copy loop, which we can't synthesise without spare regs at
    // this point in the pipeline). All known byval-args produce a
    // constant length, so this should always hit.
    Register Dst = MI.getOperand(0).getReg();
    Register Src = IsSet ? Register() : MI.getOperand(1).getReg();
    Register LenReg = IsSet ? MI.getOperand(2).getReg()
                            : MI.getOperand(2).getReg();
    auto LenVal = getIConstantVRegValWithLookThrough(LenReg, MRI);
    if (LenVal) {
      uint64_t N = LenVal->Value.getZExtValue();
      LLT I8 = LLT::scalar(8);
      LLT PtrTy = LLT::pointer(0, 16);
      LLT OffTy = LLT::scalar(16);
      MachineFunction *MF = MI.getParent()->getParent();
      auto *DstMMO0 = *MI.memoperands_begin();
      auto *SrcMMO0 = IsSet ? nullptr : *std::next(MI.memoperands_begin());
      Register SetVal = IsSet ? MI.getOperand(1).getReg() : Register();
      for (uint64_t i = 0; i < N; ++i) {
        Register Off = Builder.buildConstant(OffTy, i).getReg(0);
        Register CurDst = Builder.buildPtrAdd(PtrTy, Dst, Off).getReg(0);
        auto *DstMMO = MF->getMachineMemOperand(DstMMO0, i, I8);
        Register Byte;
        if (IsSet) {
          Byte = SetVal;  // i8 fill byte (already legal as scalar(8))
        } else {
          Register CurSrc = Builder.buildPtrAdd(PtrTy, Src, Off).getReg(0);
          auto *SrcMMO = MF->getMachineMemOperand(SrcMMO0, i, I8);
          Byte = Builder.buildLoad(I8, CurSrc, *SrcMMO).getReg(0);
        }
        Builder.buildStore(Byte, CurDst, *DstMMO);
      }
      MI.eraseFromParent();
      return true;
    }
    // Fall through to libcall (and report failure) if length not
    // constant. The verifier will then surface it loudly rather than
    // silently emitting a nested ADJCALLSTACK.
  }

  uint32_t SizeLimit;
  if (IsInline) {
    SizeLimit = UINT16_MAX;
  } else {
    MachineFunction *MF = MI.getParent()->getParent();
    if (MF && MF->getFunction().hasMinSize()) {
      // Copies:
      // => inline LDA/STA: 6n bytes
      // => memcpy(): ~23 bytes
      // Sets:
      // => inline LDA/STA: 2 + 3n bytes
      // => __memset(): ~21? bytes
      SizeLimit = IsSet ? 6 : 3;
    } else if (!MF || MF->getFunction().hasOptSize()) {
      SizeLimit = IsSet ? 8 : 4;
    } else {
      SizeLimit = IsSet ? 16 : 8;
    }
  }

  LegalizerHelper::LegalizeResult Result;

  // Try lowering, keeping in mind the size limit.
  if (IsInline) {
    Result = Helper.lowerMemcpyInline(MI);
  } else {
    Result = Helper.lowerMemCpyFamily(MI, SizeLimit);
  }
  if (Result == LegalizerHelper::Legalized) {
    return true;
  }

  // Try emitting a libcall.
  Result = Helper.createMemLibcall(MRI, MI, LocObserver);
  if (Result == LegalizerHelper::Legalized) {
    MI.eraseFromParent();
    return true;
  }

  return false;
}

static bool willBeStaticallyAllocated(const MachineOperand &MO) {
  const MachineFunction &MF = *MO.getParent()->getMF();
  assert(MO.isFI());
  return !MF.getFrameInfo().isFixedObjectIndex(MO.getIndex());
}

std::optional<MachineOperand> MC6809LegalizerInfo::matchAbsoluteAddressing(MachineRegisterInfo &MRI, Register Addr) const {
  int64_t Offset = 0;

  while (true) {
    if (auto ConstAddr = getIConstantVRegValWithLookThrough(Addr, MRI)) {
      return MachineOperand::CreateImm(Offset + ConstAddr->Value.getSExtValue());
    }
    if (const MachineInstr *GVAddr = getOpcodeDef(G_GLOBAL_VALUE, Addr, MRI)) {
      const MachineOperand &GV = GVAddr->getOperand(1);
      return MachineOperand::CreateGA(GV.getGlobal(), GV.getOffset() + Offset);
    }
    if (const MachineInstr *FIAddr = getOpcodeDef(G_FRAME_INDEX, Addr, MRI)) {
      const MachineOperand &FI = FIAddr->getOperand(1);
      if (willBeStaticallyAllocated(FI)) {
        return MachineOperand::CreateFI(FI.getIndex(), FI.getOffset() + Offset);
      }
    }
    if (const auto *PtrAddAddr = cast_if_present<GPtrAdd>(getOpcodeDef(G_PTR_ADD, Addr, MRI))) {
      auto ConstOffset = getIConstantVRegValWithLookThrough(PtrAddAddr->getOffsetReg(), MRI);
      if (!ConstOffset)
        return std::nullopt;
      Offset += ConstOffset->Value.getSExtValue();
      Addr = PtrAddAddr->getBaseReg();
      continue;
    }
    return std::nullopt;
  }
  return std::nullopt;
}

static std::optional<uint64_t> getUInt64FromConstantOper(const MachineOperand &Operand) {
  if (Operand.isImm())
    return Operand.getImm();
  if (Operand.isCImm())
    return Operand.getCImm()->getZExtValue();
  return std::nullopt;
}

static MachineOperand offsetMachineOperand(MachineOperand &Operand, int64_t Offset) {
  if (Offset == 0)
    return Operand;
  if (Operand.isImm())
    return MachineOperand::CreateImm(Operand.getImm() + Offset);
  if (Operand.isCImm())
    return MachineOperand::CreateCImm(Operand.getCImm() + Offset);
  if (Operand.isGlobal())
    return MachineOperand::CreateGA(Operand.getGlobal(), Operand.getOffset() + Offset);
  if (Operand.isFI())
    return MachineOperand::CreateFI(Operand.getIndex(), Operand.getOffset() + Offset);
  llvm_unreachable("Unsupported machine operand type!");
}

template <typename T> static inline int compareNumbers(T A, T B) { return A < B ? -1 : (A > B ? 1 : 0); }

static std::optional<int> compareOperandLocations(const MachineOperand &A, const MachineOperand &B) {
  if (A.isImm() && B.isImm())
    return compareNumbers(A.getImm(), B.getImm());
  if (A.isGlobal() && B.isGlobal())
    if (A.getGlobal()->getGUID() == B.getGlobal()->getGUID())
      return compareNumbers(A.getOffset(), B.getOffset());
  return std::nullopt;
}

bool MC6809LegalizerInfo::tryTFMBlockCopy(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI) const {
  MachineIRBuilder &Builder = Helper.MIRBuilder;
  MachineFunction &MF = Builder.getMF();

  bool IsMemSet = MI.getOpcode() == MC6809::G_MEMSET;
  bool IsInline = MI.getOpcode() == MC6809::G_MEMCPY_INLINE;

  // Match supported combinations.
  if (MI.getOpcode() != MC6809::G_MEMCPY && MI.getOpcode() != MC6809::G_MEMCPY_INLINE && MI.getOpcode() != MC6809::G_MEMMOVE && MI.getOpcode() != MC6809::G_MEMSET) {
    return false;
  }

  Register DstReg = MI.getOperand(0).getReg();
  auto Dst = matchAbsoluteAddressing(MRI, DstReg);
  Register SrcReg = MI.getOperand(1).getReg();
  auto Src = matchAbsoluteAddressing(MRI, SrcReg);
  auto Len = matchAbsoluteAddressing(MRI, MI.getOperand(2).getReg());
  bool Descending = false;
  // The transfer count must be a compile-time constant for an inline TFM.
  if (!Len.has_value())
    return false;

  // A plain memcpy assumes its operands don't overlap, so the copy direction is
  // always ascending -- it can therefore take the pointers straight from
  // registers (materialized into the index pair) when they aren't compile-time
  // absolute addresses, replacing a memcpy libcall with an inline `tfm`.
  // memmove needs compile-time source/dest locations to choose the copy
  // direction, and memset's fill path needs a constant byte, so those still
  // require absolute addressing.
  bool IsPlainCopy = MI.getOpcode() == MC6809::G_MEMCPY ||
                     MI.getOpcode() == MC6809::G_MEMCPY_INLINE;
  // Track whether either pointer is a register (vs a compile-time absolute
  // address). Register pointers take the BlockCopy_* path below, which hands
  // the pointers to regalloc in the {IX,IY} class so the postbyte records
  // whichever assignment it picked -- no forced `tfr x,y` swap.
  bool UsesRegPtr = false;
  if (!Dst.has_value()) {
    if (!IsPlainCopy)
      return false;
    Dst = MachineOperand::CreateReg(DstReg, /*isDef=*/false);
    UsesRegPtr = true;
  }
  if (!Src.has_value()) {
    if (!IsPlainCopy)
      return false;
    Src = MachineOperand::CreateReg(SrcReg, /*isDef=*/false);
    UsesRegPtr = true;
  }

  if (IsMemSet) {
    // A TII-based memory set is always slower than the alternative.
    // Skip using it unless -Os, -Oz is set.
    if (!MF.getFunction().hasOptSize())
      return false;

    auto SrcValue = getUInt64FromConstantOper(Src.value());
    if (!SrcValue.has_value())
      return false;
    if (MRI.getType(SrcReg).getSizeInBytes() != 1)
      return false;
  }
  if (MI.getOpcode() == MC6809::G_MEMMOVE) {
    auto OperandOrder = compareOperandLocations(Src.value(), Dst.value());
    // TODO: Handle case when two G_MEMMOVE destinations cannot alias.
    if (!OperandOrder.has_value())
      return false;
    if (OperandOrder.value() == -1)
      Descending = true;
  }

  // On 6309 platforms, block copies can be emitted, and sets can be done
  // with them too. However, some requirements have to be considered.
  // The source, destination, and length have to be constant; however,
  // they can be opaque constants (such as symbols).
  // Each transfer is 6 + 3n cycles, where n is the length
  // of the transfer in bytes.
  uint64_t BytesPerTransfer = UINT16_MAX;
  uint64_t SizeMin, SizeMax;
  if (MF.getFunction().hasMinSize()) {
    SizeMin = IsMemSet ? 5 : 2;
    SizeMax = IsMemSet ? (BytesPerTransfer * 2 + 1) : (BytesPerTransfer * 3);
  } else if (MF.getFunction().hasOptSize()) {
    SizeMin = IsMemSet ? 5 : 4;
    SizeMax = IsMemSet ? (BytesPerTransfer * 3 + 1) : (BytesPerTransfer * 4);
  } else {
    SizeMin = 5;
    SizeMax = BytesPerTransfer * 5;
  }
  if (IsInline)
    SizeMax = UINT16_MAX;
  // At -Os/-Oz keep register-pointer copies on the shared memcpy libcall: the
  // memcpy body is already linked in for other callers, so an inline TFM only
  // adds per-site bytes there. At speed levels the inline TFM is faster (no call
  // overhead), and with the order-free assignment there is no swap penalty, so
  // the normal length minimum applies. (Compile-time-absolute copies materialize
  // their pointers for free via leax/leay and inline at every level.)
  if (UsesRegPtr && MF.getFunction().hasOptSize())
    return false;
  uint64_t KnownLen = UINT16_MAX;
  auto LenValue = getUInt64FromConstantOper(Len.value());
  if (LenValue.has_value()) {
    KnownLen = LenValue.value();
    if (KnownLen < SizeMin || KnownLen > SizeMax) {
      return false;
    }
  } else if (BytesPerTransfer < UINT16_MAX || Descending) {
    return false;
  }

  auto DstPointerInfo = MI.memoperands()[0]->getPointerInfo();
  auto SrcPointerInfo = MI.memoperands()[IsMemSet ? 0 : 1]->getPointerInfo();

  // Proceed with the custom lowering.
  if (IsMemSet) {
    // Emit a G_STORE, then set Src = Dst, Dst = Dst + 1, Len = Len - 1.
    auto StoreReg = MRI.createGenericVirtualRegister(LLT::scalar(8));
    Builder.buildConstant(StoreReg, getUInt64FromConstantOper(Src.value()).value() & 0xFF);
    Builder.buildStore(StoreReg, DstReg, *MF.getMachineMemOperand(SrcPointerInfo, MachineMemOperand::MOStore, 1, Align(1)));
    Src = Dst;
    Dst = offsetMachineOperand(Dst.value(), 1);
    DstPointerInfo = DstPointerInfo.getWithOffset(1);
    Len = offsetMachineOperand(Len.value(), -1);
    KnownLen -= 1;
  }

  // Materialize each address-typed operand (FrameIndex / GlobalAddress /
  // Immediate / Reg) into a generic pointer vreg up front, so the block
  // transfer gets clean register operands that flow normally through
  // regbank-select / isel. emitBlockCopy then COPYs those into the
  // REGTFM ({IX,IY}) class the BlockCopy_* pseudo expects.
  LLT P = LLT::pointer(0, 16);
  LLT S16 = LLT::scalar(16);
  auto materializeAddrIntoReg = [&](const MachineOperand &MO,
                                     int64_t ExtraOffset) -> Register {
    Register Vreg = MRI.createGenericVirtualRegister(P);
    if (MO.isReg()) {
      if (ExtraOffset == 0) {
        Builder.buildCopy(Vreg, MO.getReg());
      } else {
        auto Cst = Builder.buildConstant(S16, ExtraOffset);
        Builder.buildPtrAdd(Vreg, MO.getReg(), Cst);
      }
      return Vreg;
    }
    if (MO.isImm()) {
      Builder.buildConstant(Vreg, MO.getImm() + ExtraOffset);
      return Vreg;
    }
    if (MO.isGlobal()) {
      Builder.buildInstr(TargetOpcode::G_GLOBAL_VALUE)
          .addDef(Vreg)
          .addGlobalAddress(MO.getGlobal(), MO.getOffset() + ExtraOffset);
      return Vreg;
    }
    if (MO.isFI()) {
      Register FIReg = MRI.createGenericVirtualRegister(P);
      Builder.buildInstr(TargetOpcode::G_FRAME_INDEX)
          .addDef(FIReg)
          .addFrameIndex(MO.getIndex());
      int64_t Total = MO.getOffset() + ExtraOffset;
      if (Total == 0)
        return FIReg;
      auto Cst = Builder.buildConstant(S16, Total);
      Builder.buildPtrAdd(Vreg, FIReg, Cst);
      return Vreg;
    }
    llvm_unreachable("Unexpected operand type from matchAbsoluteAddressing");
  };

  // The single block-transfer emitter for every TFM-able memcpy / memmove /
  // memset, whether the pointers are compile-time-absolute addresses or live
  // registers. Each pointer is materialized into a REGTFM ({IX,IY}) vreg and
  // handed to a BlockCopy_* pseudo, which post-RA expands to the real TFM
  // reading the *allocated* registers. Letting regalloc pick the IX/IY
  // assignment means an absolute global materializes straight into its index
  // register (the coalescer folds the COPY -> leax/ldx direct, no shuffle) and
  // a register pointer already in X no longer forces a `tfr x,y` swap. BlockOpc
  // selects the increment mode: Inc_Inc (ascending copy), Dec_Dec (descending
  // memmove), or Stay_Inc (memset fill -- src holds the byte and stays put).
  auto emitBlockCopy = [&](const MachineOperand &SrcMO,
                           const MachineOperand &DstMO, int64_t ExtraOffset,
                           const MachineOperand &CountMO, unsigned BlockOpc,
                           MachinePointerInfo SrcPI, MachinePointerInfo DstPI) {
    Register SrcTFM = MRI.createVirtualRegister(&MC6809::REGTFMRegClass);
    Builder.buildCopy(SrcTFM, materializeAddrIntoReg(SrcMO, ExtraOffset));
    Register DstTFM = MRI.createVirtualRegister(&MC6809::REGTFMRegClass);
    Builder.buildCopy(DstTFM, materializeAddrIntoReg(DstMO, ExtraOffset));
    // Put the byte count into the W register the TFM reads. BlockCopy carries
    // AW implicitly (its Defs/Uses), so the count is not an explicit operand.
    // Stay target-opcode-free pre-RA: a generic G_CONSTANT (immediate length)
    // or the incoming count register, COPYd to AW — the selector lowers the
    // constant load / transfer, the coalescer folds the COPY when the value
    // already lands in W.
    Register CountV = CountMO.isImm()
                          ? Builder.buildConstant(LLT::scalar(16), CountMO.getImm())
                                .getReg(0)
                          : CountMO.getReg();
    Builder.buildCopy(MC6809::AW, CountV);
    // The pseudo's pointer operands are tied def+use: the TFM post-increments
    // them, so it clobbers the registers. The write-back defs are dead, but the
    // tie makes a pointer that is still live after the copy interfere with the
    // register the TFM destroys, so regalloc keeps it in its own register.
    Register SrcWB = MRI.createVirtualRegister(&MC6809::REGTFMRegClass);
    Register DstWB = MRI.createVirtualRegister(&MC6809::REGTFMRegClass);
    Builder.buildInstr(BlockOpc)
        .addDef(SrcWB)
        .addDef(DstWB)
        .addUse(SrcTFM)
        .addUse(DstTFM)
        .addMemOperand(MF.getMachineMemOperand(SrcPI, MachineMemOperand::MOLoad,
                                               1, Align(1)))
        .addMemOperand(MF.getMachineMemOperand(DstPI, MachineMemOperand::MOStore,
                                               1, Align(1)));
  };

  // Pick the TFM increment mode: a memset fills via Stay_Inc (the byte stays
  // under the source pointer while the destination sweeps the range), a
  // direction-resolved memmove descends via Dec_Dec, everything else is an
  // ascending Inc_Inc copy.
  unsigned BlockOpc = IsMemSet      ? MC6809::BlockCopy_Stay_Inc
                      : Descending  ? MC6809::BlockCopy_Dec_Dec
                                    : MC6809::BlockCopy_Inc_Inc;

  // Note that Descending transfers must be done in backwards order.
  if (KnownLen <= BytesPerTransfer) {
    uint64_t AdjOfs = Descending ? (KnownLen - 1) : 0;
    emitBlockCopy(Src.value(), Dst.value(), AdjOfs, Len.value(), BlockOpc,
                  SrcPointerInfo, DstPointerInfo);
  } else {
    for (uint64_t TOfs = 0; TOfs < KnownLen; TOfs += BytesPerTransfer) {
      uint64_t TLen = std::min(KnownLen - TOfs, BytesPerTransfer);
      uint64_t AdjTOfs = Descending ? (KnownLen - TOfs - 1) : TOfs;
      uint64_t AdjTOfsMO = Descending ? (KnownLen - TOfs - TLen) : TOfs;
      MachineOperand TLenMO = MachineOperand::CreateImm(TLen);
      emitBlockCopy(Src.value(), Dst.value(), AdjTOfs, TLenMO, BlockOpc,
                    SrcPointerInfo.getWithOffset(AdjTOfsMO),
                    DstPointerInfo.getWithOffset(AdjTOfsMO));
    }
  }

  MI.eraseFromParent();
  return true;
}

bool MC6809LegalizerInfo::legalizeIntrinsic(LegalizerHelper &Helper, MachineInstr &MI) const {
  LLT P = LLT::pointer(0, 16);
  MachineIRBuilder &Builder = Helper.MIRBuilder;
  switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
  case Intrinsic::trap: {
    auto &Ctx = MI.getMF()->getFunction().getContext();
    auto *RetTy = Type::getVoidTy(Ctx);
    LostDebugLocObserver LocObserver("");
    if (!Helper.createLibcall("abort", {{}, RetTy, 0}, {}, CallingConv::C, LocObserver)) {
      return false;
    }
    MI.eraseFromParent();
    return true;
  }
  case Intrinsic::vacopy: {
    MachinePointerInfo MPO;
    auto Tmp = Builder.buildLoad(P, MI.getOperand(2), *MI.getMF()->getMachineMemOperand(MPO, MachineMemOperand::MOLoad, 2, Align()));
    Builder.buildStore(Tmp, MI.getOperand(1), *MI.getMF()->getMachineMemOperand(MPO, MachineMemOperand::MOStore, 2, Align()));
    MI.eraseFromParent();
    return true;
  }
  }
  return false;
}

//===----------------------------------------------------------------------===//
// Integer Extension and Truncation
//===----------------------------------------------------------------------===//

static auto unmergeDefs(MachineInstr *MI) {
  assert(MI->getOpcode() == TargetOpcode::G_UNMERGE_VALUES);
  return make_range(MI->operands_begin(), MI->operands_end() - 1);
}

// Whether or not it's worth shifting/rotating by 8 (in a type one byte wider
// for shifts) and shifting/rotating in the opposite direction by 8-n.
static bool shouldOverCorrect(uint64_t Amt, LLT Ty, bool IsRotate) {
  assert(Amt < 8);

  if (IsRotate)
    return Amt > 4;

  // Never over-correct an 8-bit shift. A constant i8 shift by 1..7 is at most
  // 7 native single-byte instructions (aslb/lsrb/asrb chains via the single-bit
  // G_SHLE/G_LSHRE path), so widening to 16 bits never pays. Worse, the widened
  // path emits an i16 shl-8 + i16 lshr-(8-Amt); the i16 small-shift byte-algebra
  // decomposition then emits an i8 shl-(8-N) cross term that widens straight
  // back here -- an infinite mutual recursion. (Historically this path also
  // routed i8 ashr-7 through __ashlhi3/__lshrhi3; see the ADJCALLSTACK pitfall
  // note in legalizeSExt.)
  if (Ty == LLT::scalar(8))
    return false;

  // The over-correct path widens to Ty+8 bits. Only use it when the wider
  // type is a legal power-of-2 size (s8, s16, s32). Non-power-of-2 types
  // like s40 (from s32+8) can't be legalized and cause infinite cycles.
  unsigned WiderBits = Ty.getSizeInBits() + 8;
  if (WiderBits != 8 && WiderBits != 16 && WiderBits != 32)
    return false;

  // The choice is between emitting Amt operations at width Ty, or emitting 8 -
  // Amt operations (in the opposite direction) at width Ty + 8.
  return Amt * Ty.getSizeInBytes() > (8 - Amt) * (Ty.getSizeInBytes() + 1);
}

bool MC6809LegalizerInfo::legalizeShiftRotate(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  MachineIRBuilder &Builder = Helper.MIRBuilder;

  auto [Dst, Src, AmtReg] = MI.getFirst3Regs();

  bool IsRotate = MI.getOpcode() == G_ROTL || MI.getOpcode() == G_ROTR;

  LLT Ty = MRI.getType(Dst);
  assert(Ty == MRI.getType(Src));
  assert(Ty.isByteSized());

  LLT S1 = LLT::scalar(1);
  LLT S8 = LLT::scalar(8);

  // i16 / i32 / i64 shifts (non-rotates).
  //
  // A *constant*-amount i16 shl/lshr/ashr is left for the instruction selector:
  // selectShift16 emits the native single-bit carry chain on the value's own
  // 16-bit home -- ASLD/LSRD/ASRD on hd6309, and ASLB+ROLA / LSRA+RORB /
  // ASRA+RORB on base 6809 (with the in-memory asl/rol chain when the value is
  // spilled). The chain shifts D (or the spill slot) in place and uses no extra
  // accumulator temporaries, so it does NOT hit the old ACC16_D pressure trap
  // that a byte-level decomposition does -- and ACC16_D itself was removed
  // (see MC6809RegisterInfo.td). That trap is the only reason this used to be a
  // blanket libcall (it cost rand_r / ubsan_val_to_imax their allocation).
  //
  // Variable i16 shifts and all i32/i64 shifts still go to the hand-written
  // assembly libcalls in compiler-rt/lib/builtins/mc6809/ (__ashlhi3,
  // __ashrhi3, __lshrhi3, __ashlsi3, ..., __ashldi3, __ashrdi3, __lshrdi3).
  if (Ty.getSizeInBits() >= 16 && !IsRotate) {
    if (Ty.getSizeInBits() == 16 &&
        getIConstantVRegValWithLookThrough(AmtReg, MRI))
      return true; // selectShift16 handles constant i16 shifts
    LLT AmtTy = MRI.getType(AmtReg);
    if (AmtTy != S8)
      MI.getOperand(2).setReg(Builder.buildTrunc(S8, AmtReg).getReg(0));
    return shiftRotateLibcall(Helper, MRI, MI, LocObserver);
  }

  // Presently, only left shifts by one bit are supported.
  auto ConstantAmt = getIConstantVRegValWithLookThrough(AmtReg, MRI);
  if (!ConstantAmt) {
    if (!isPowerOf2_32(Ty.getSizeInBits())) {
      return IsRotate ? Helper.lowerRotate(MI) : Helper.widenScalar(MI, 0, LLT::scalar(NextPowerOf2(Ty.getSizeInBits())));
    }
    if (Ty.getSizeInBits() > 64) {
      return IsRotate ? Helper.lowerRotate(MI) : Helper.narrowScalar(MI, 0, LLT::scalar(64));
    }
    if (IsRotate)
      return legalizeFunnelShift(Helper, MRI, MI, LocObserver);
    LLT AmtTy = MRI.getType(AmtReg);
    if (AmtTy != S8)
      MI.getOperand(2).setReg(Builder.buildTrunc(S8, AmtReg).getReg(0));
    return shiftRotateLibcall(Helper, MRI, MI, LocObserver);
  }

  uint64_t Amt = ConstantAmt->Value.getZExtValue();

  // This forms the base case for the problem decompositions below.
  if (Amt == 0) {
    Builder.buildCopy(Dst, Src);
    MI.eraseFromParent();
    return true;
  }

  Register Partial;
  Register NewAmt;
  // Shift by one multiples of one byte.
  if (Amt >= 8) {
    auto Unmerge = Builder.buildUnmerge(S8, Src);
    SmallVector<Register> DstBytes;
    for (MachineOperand &Op : unmergeDefs(Unmerge))
      DstBytes.push_back(Op.getReg());
    Register Fill;
    switch (MI.getOpcode()) {
    default:
      llvm_unreachable("Invalid opcode.");
    case G_ROTL:
    case G_ROTR:
      break;
    case G_ASHR: {
      Register Sign = Builder.buildICmp(ICmpInst::ICMP_SLT, S1, Src, Builder.buildConstant(Ty, 0)).getReg(0);
      Fill = Builder.buildSExt(S8, Sign).getReg(0);
      break;
    }
    case G_LSHR:
    case G_SHL:
      Fill = Builder.buildConstant(S8, 0).getReg(0);
      break;
    }
    // Instead of decomposing the problem recursively byte-by-byte, looping here
    // ensures that Fill is reused for G_ASHR.
    while (Amt >= 8) {
      switch (MI.getOpcode()) {
      default:
        llvm_unreachable("Invalid opcode.");
      case G_LSHR:
      case G_ASHR:
      case G_SHL:
        break;
      case G_ROTR:
        Fill = DstBytes.front();
        break;
      case G_ROTL:
        Fill = DstBytes.back();
        break;
      }
      switch (MI.getOpcode()) {
      default:
        llvm_unreachable("Invalid opcode.");
      case G_LSHR:
      case G_ASHR:
      case G_ROTR:
        DstBytes.erase(DstBytes.begin());
        DstBytes.push_back(Fill);
        break;
      case G_SHL:
      case G_ROTL:
        DstBytes.pop_back();
        DstBytes.insert(DstBytes.begin(), Fill);
        break;
      }
      Amt -= 8;
    }
    assert(Amt < 8);
    Partial = Builder.buildMergeValues(Ty, DstBytes).getReg(0);
    NewAmt = Builder.buildConstant(S8, Amt).getReg(0);
  } else if (shouldOverCorrect(Amt, Ty, IsRotate)) {
    Register LeftAmt, RightAmt;
    switch (MI.getOpcode()) {
    default:
      llvm_unreachable("Invalid opcode.");
    case G_SHL:
    case G_ROTL:
      if (Ty == S8 && MI.getOpcode() == G_ROTL)
        LeftAmt = Builder.buildConstant(S8, 0).getReg(0);
      else
        LeftAmt = Builder.buildConstant(S8, 8).getReg(0);
      RightAmt = Builder.buildConstant(S8, 8 - Amt).getReg(0);
      break;
    case G_LSHR:
    case G_ASHR:
    case G_ROTR:
      LeftAmt = Builder.buildConstant(S8, 8 - Amt).getReg(0);
      if (Ty == S8 && MI.getOpcode() == G_ROTR)
        RightAmt = Builder.buildConstant(S8, 0).getReg(0);
      else
        RightAmt = Builder.buildConstant(S8, 8).getReg(0);
    }
    if (IsRotate) {
      auto Left = Builder.buildRotateLeft(Ty, Src, LeftAmt);
      Builder.buildRotateRight(Dst, Left, RightAmt);
    } else {
      // Round up to the next power-of-2 width, not just +8. The +8 form
      // produced non-power-of-2 widths (s16 → s24, s32 → s40) which the
      // upstream lowerEXT can't handle and which feed back into a
      // legalization loop via clampScalar widening.
      LLT WideTy = LLT::scalar(NextPowerOf2(Ty.getSizeInBits() + 1));
      Register WideSrc;
      switch (MI.getOpcode()) {
      default:
        llvm_unreachable("Invalid opcode.");
      case G_SHL:
        WideSrc = Builder.buildAnyExt(WideTy, Src).getReg(0);
        break;
      case G_LSHR:
        WideSrc = Builder.buildZExt(WideTy, Src).getReg(0);
        break;
      case G_ASHR:
        WideSrc = Builder.buildSExt(WideTy, Src).getReg(0);
        break;
      }
      auto Left = Builder.buildShl(WideTy, WideSrc, LeftAmt);
      auto Right = Builder.buildLShr(WideTy, Left, RightAmt).getReg(0);
      Builder.buildTrunc(Dst, Right);
    }
    MI.eraseFromParent();
    return true;
  } else {
    // Shift by one, then shift the remainder.

    Register CarryIn;
    switch (MI.getOpcode()) {
    default:
      llvm_unreachable("Invalid opcode.");
    case G_SHL:
    case G_LSHR:
      CarryIn = Builder.buildConstant(S1, 0).getReg(0);
      break;
    case G_ROTR: {
      // Once selected, this places the low bit in the carry flag.
      Register LowByte = (Ty == S8) ? Src : Builder.buildUnmerge(S8, Src).getReg(0);
      CarryIn = Builder.buildInstr(MC6809::G_LSHRE, {S8, S1}, {LowByte, Builder.buildUndef(S1)}).getReg(1);
      break;
    }
    case G_ASHR:
    case G_ROTL: {
      // Once selected, this places the high bit in the carry flag.
      Register HighByte = (Ty == S8) ? Src : Builder.buildUnmerge(S8, Src).getReg(Ty.getSizeInBytes() - 1);
      CarryIn = Builder.buildICmp(ICmpInst::ICMP_UGE, S1, HighByte, Builder.buildConstant(S8, 0x80)).getReg(0);
      break;
    }
    }

    unsigned Opcode;
    switch (MI.getOpcode()) {
    default:
      llvm_unreachable("Invalid opcode.");
    case G_SHL:
    case G_ROTL:
      Opcode = MC6809::G_SHLE;
      break;
    case G_LSHR:
    case G_ASHR:
    case G_ROTR:
      Opcode = MC6809::G_LSHRE;
      break;
    }
    auto Even = Builder.buildInstr(Opcode, {Ty, S1}, {Src, CarryIn});
    Partial = Even.getReg(0);
    if (!legalizeLshrEShlE(Helper, MRI, *Even, LocObserver))
      return false;
    NewAmt = Builder.buildConstant(S8, Amt - 1).getReg(0);
  }

  Helper.Observer.changingInstr(MI);
  MI.getOperand(1).setReg(Partial);
  MI.getOperand(2).setReg(NewAmt);
  Helper.Observer.changedInstr(MI);
  return true;
}

bool MC6809LegalizerInfo::legalizeLshrEShlE(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI) const {
  MachineIRBuilder &Builder = Helper.MIRBuilder;
  LLT S1 = LLT::scalar(1);
  LLT S8 = LLT::scalar(8);

  auto [Dst, CarryOut, Src, CarryIn] = MI.getFirst4Regs();
  LLT Ty = MRI.getType(Dst);
  if (Ty == S8)
    return true;

  auto Unmerge = Builder.buildUnmerge(S8, Src);
  SmallVector<Register> Parts;

  SmallVector<Register> Defs;
  for (MachineOperand &SrcPart : unmergeDefs(Unmerge))
    Defs.push_back(SrcPart.getReg());

  if (MI.getOpcode() == MC6809::G_LSHRE)
    std::reverse(Defs.begin(), Defs.end());

  Register Carry = CarryIn;
  for (const auto &I : enumerate(Defs)) {
    Parts.push_back(MRI.createGenericVirtualRegister(S8));
    Register NewCarry = I.index() == Defs.size() - 1 ? CarryOut : MRI.createGenericVirtualRegister(S1);
    Builder.buildInstr(MI.getOpcode(), {Parts.back(), NewCarry}, {I.value(), Carry});
    Carry = NewCarry;
  }

  if (MI.getOpcode() == MC6809::G_LSHRE)
    std::reverse(Parts.begin(), Parts.end());

  Builder.buildMergeValues(Dst, Parts).getReg(0);
  MI.eraseFromParent();
  return true;
}

bool MC6809LegalizerInfo::legalizeLshrEShlE(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const { return legalizeLshrEShlE(Helper, MRI, MI); }

// Load pointers by loading a 16-bit integer, then converting to pointer. This
// allows the 16-bit loads to be reduced to a pair of 8-bit loads.
bool MC6809LegalizerInfo::legalizeLoad(LegalizerHelper &Helper, MachineRegisterInfo &MRI, GAnyLoad &MI, LostDebugLocObserver &LocObserver) const {

  MachineIRBuilder &Builder = Helper.MIRBuilder;
  Builder.setInsertPt(Builder.getMBB(), std::next(Builder.getInsertPt()));
  Register Tmp;
  const MachineMemOperand &MMO = **MI.memoperands_begin();
  switch (MI.getOpcode()) {
  case G_SEXTLOAD:
    Tmp = MRI.createGenericVirtualRegister(MMO.getType());
    Builder.buildSExt(MI.getDstReg(), Tmp);
    break;
  case G_ZEXTLOAD:
    Tmp = MRI.createGenericVirtualRegister(MMO.getType());
    Builder.buildZExt(MI.getDstReg(), Tmp);
    break;
  default: {
    auto DstType = MRI.getType(MI.getDstReg());
    if (DstType.isPointer()) {
      Tmp = MRI.createGenericVirtualRegister(LLT::scalar(DstType.getScalarSizeInBits()));
      Builder.buildIntToPtr(MI.getDstReg(), Tmp);
    } else {
      // Bug #310 (2026-05-19): scalar G_LOAD with dst type wider
      // than the MMO memory type (partial-width load).  Split into
      // a G_LOAD of MMO-size followed by a G_ZEXT to the dst type.
      // Defined-zero high bytes are sufficient for all observed
      // shapes (the typical consumer is a G_TRUNC back down to
      // mem-size width, which doesn't read the high bytes anyway).
      assert(DstType.isScalar() &&
             "legalizeLoad default branch expects pointer or scalar dst");
      Tmp = MRI.createGenericVirtualRegister(MMO.getType());
      Builder.buildZExt(MI.getDstReg(), Tmp);
    }
    break;
  }
  }
  Helper.Observer.changingInstr(MI);
  MI.setDesc(Builder.getTII().get(G_LOAD));
  MI.getOperand(0).setReg(Tmp);
  Helper.Observer.changedInstr(MI);
  return true;
}

bool MC6809LegalizerInfo::shiftRotateLibcall(LegalizerHelper &Helper, MachineRegisterInfo &MRI, MachineInstr &MI, LostDebugLocObserver &LocObserver) const {
  unsigned Size = MRI.getType(MI.getOperand(0).getReg()).getSizeInBits();
  auto &Ctx = MI.getMF()->getFunction().getContext();

  auto Libcall = Helper.getRTLibDesc(MI.getOpcode(), Size);

  Type *HLTy = IntegerType::get(Ctx, Size);
  // The shift amount matches the C runtime signature's `int` type.
  // For i32 and i64 shifts, declare it as i16 so it lands on the
  // stack — B gets clobbered by the i32/i64 arg stack setup, so
  // passing the amount in B is unreliable. For ≤ i16 shifts, i8
  // is fine (amount in B, no conflict).
  unsigned AmtBits = (Size >= 32) ? 16 : 8;
  Type *HLAmtTy = IntegerType::get(Ctx, AmtBits);

  // For i64 shifts, the amount is declared as i16 (on the stack)
  // because B gets clobbered by the i64 arg setup. Widen the s8
  // vreg to match. For ≤ 32-bit shifts the amount stays i8 (in B).
  MachineIRBuilder &B = Helper.MIRBuilder;
  Register AmtReg = MI.getOperand(2).getReg();
  if (AmtBits > 8) {
    LLT AmtLLT = MRI.getType(AmtReg);
    if (AmtLLT.getSizeInBits() < AmtBits)
      AmtReg = B.buildZExt(LLT::scalar(AmtBits), AmtReg).getReg(0);
  }

  SmallVector<CallLowering::ArgInfo, 3> Args;
  Args.push_back({MI.getOperand(1).getReg(), HLTy, 0});
  Args.push_back({AmtReg, HLAmtTy, 1});
  if (!Helper.createLibcall(Libcall, {MI.getOperand(0).getReg(), HLTy, 0}, Args, LocObserver))
    return false;

  MI.eraseFromParent();
  return true;
}
